INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (43, 19, '논문', 'Proton pump inhibitor and histamine 2 receptor antagonist use and vitamin B12 deficiency (JAMA 2013)', 'https://pubmed.ncbi.nlm.nih.gov/24327038/', '24327038', NULL, 'Previous and current gastric acid inhibitor use was significantly associated with the presence of vitamin B12 deficiency.', 'pmid_ok_quote_ok');
