INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (102, 44, '식약처_의약품허가', '로칼트롤연질캡슐0.25마이크로그람(칼시트리올) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200610653', NULL, NULL, '1) 이 약은 비타민 D3의 가장 효과적인 활성 대사체로 비타민 D 및 그 유도체와의 병용에 의해 상가 작용 및 고칼슘혈증이 나타날 수 있으므로 병용하지 않아야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (103, 44, '식약처_의약품허가', '원알파정(알파칼시돌) 사용상의 주의사항 - 2. 이 약을 복용하는 동안 다음의 약을 복용하지 말 것.', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199001232', NULL, NULL, '2) 비타민 D와 그 유도체(상가작용 및 고칼슘혈증이 나타날 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (104, 45, '식약처_의약품허가', '메가디쓰리정25000아이유(콜레칼시페롤농축분말) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201701511', NULL, NULL, '4) 비타민D농도가 증가되면 고칼슘혈증을 유발할 수 있으며, 부가적인 수축촉진 효과로 인해 디기탈리스 독성과 심각한 부정맥의 위험을 증가시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (105, 45, '식약처_의약품허가', '네오칼시돌연질캡슐1마이크로그램(알파칼시돌) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202503410', NULL, NULL, '4) 디기탈리스를 복용 중인 환자(고칼슘혈증으로 심부정맥이 갑자기 유발될 수 있으므로 병용시 신중을 기할 것.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (106, 45, '식약처_의약품허가', '디고신정(디곡신) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=196300001', NULL, NULL, '3) 전해질평형실조(저칼륨혈증, 고칼륨혈증, 고칼슘혈증, 저마그네슘혈증) 환자', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (107, 45, '논문', 'Digoxin, hypercalcaemia, and cardiac conduction (Postgrad Med J 1999)', 'https://pubmed.ncbi.nlm.nih.gov/10616693/', '10616693', NULL, 'concomitant therapy with digoxin or underlying cardiac disease can potentiate the arrhythmogenic effects of hypercalcaemia', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (108, 46, '논문', 'Rifampicin and vitamin D metabolism (Clin Pharmacol Ther 1980)', 'https://pubmed.ncbi.nlm.nih.gov/7379450/', '7379450', NULL, 'resulted in a consistent fall in plasma 25-hydroxycholecalciferol (25-OHD) levels of around 70%', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (109, 46, '논문', 'Effect of rifampicin and isoniazid on vitamin D metabolism (Clin Pharmacol Ther 1982)', 'https://pubmed.ncbi.nlm.nih.gov/7116768/', '7116768', NULL, 'reduced circulating levels of 25-hydroxy vitamin D (25-OHD) and 1 alpha, 25-dihydroxy vitamin D (1,25(OH)2D) by 34%', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (110, 47, '식약처_의약품허가', '제니칼캡슐120밀리그램(오르리스타트) 사용상의 주의사항 - 4. 일반적 주의', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200008801', NULL, NULL, '비타민 보충제는 1일 1회 이 약 투여 최소 2시간 이전 또는 취침시와 같이 이 약 투여 최소 2시간 후에 복용해야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (111, 47, '식약처_의약품허가', '포사맥스플러스디정 사용상의 주의사항 - 5. 상호작용(콜레칼시페롤)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200711426', NULL, NULL, '얼레스트라(Olestra), 광물성 기름, 오르리스타트(orlistat), 담즙산 제거약(예. 콜레스티라민, 콜레스티폴)은 비타민 D의 흡수를 저해할 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (112, 47, '식약처_의약품허가', '제니칼캡슐120밀리그램(오르리스타트) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200008801', NULL, NULL, '3) 이 약 투여에 의해 몇몇 지용성 비타민 및 베타카로틴 흡수가 감소될 수 있으므로, 적절한 영양 상태가 유지될 수 있도록 환자들로 하여금 지용성 비타민 함유 종합 비타민 보충제를 복용하도록 권장해야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (113, 47, '논문', 'Effects of orlistat on fat-soluble vitamins in obese adolescents (Pharmacotherapy 2002)', 'https://pubmed.ncbi.nlm.nih.gov/12126214/', '12126214', NULL, 'It may be prudent to monitor vitamin D concentrations in adolescents who take orlistat, even when a multivitamin is prescribed.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (114, 48, '식약처_의약품허가', '메가디쓰리정25000아이유(콜레칼시페롤농축분말) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201701511', NULL, NULL, '2) 콜레스티라민과 같은 이온 교환 수지 또는 파라핀 오일과 같은 완하제의 동시투여는 비타민D의 위장흡수를 감소시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (115, 48, '식약처_의약품허가', '네오칼시돌연질캡슐1마이크로그램(알파칼시돌) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202503410', NULL, NULL, '5) 콜레스티라민 같은 수지나 사하제인 미네랄 오일을 복용 중인 환자(이 약의 장관흡수가 저하될 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (116, 48, '식약처_의약품허가', '포사맥스플러스디정 사용상의 주의사항 - 5. 상호작용(콜레칼시페롤)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200711426', NULL, NULL, '얼레스트라(Olestra), 광물성 기름, 오르리스타트(orlistat), 담즙산 제거약(예. 콜레스티라민, 콜레스티폴)은 비타민 D의 흡수를 저해할 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (117, 48, '식약처_의약품허가', '로칼트롤연질캡슐0.25마이크로그람(칼시트리올) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200610653', NULL, NULL, '9) 콜레스티라민 및 세벨라머를 포함하는 담즙산 결합수지나 사하제인 미네랄 오일에 의해 이 약의 장관 흡수가 저하될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (118, 48, '논문', 'Effects of long-term cholestyramine administration on vitamin D and parathormone levels in middle-aged men with hypercholesterolemia (J Lab Clin Med 1992)', 'https://pubmed.ncbi.nlm.nih.gov/1583392/', '1583392', NULL, 'There were no differences in plasma levels of calcium (2.3 +/- 0.1 mmol/L vs 2.3 +/- 0.1 mmol/L)', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (119, 49, '식약처_의약품허가', '메가디쓰리정25000아이유(콜레칼시페롤농축분말) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201701511', NULL, NULL, '1) 페니토인 또는 바비트레이트류의 병용투여는 비타민D 대사속도를 증가시켜 비타민D의 작용을 감소시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (120, 49, '식약처_의약품허가', '환인히단토인정(페니토인) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197500285', NULL, NULL, '12) 근골격계 : 연용에 의해 구루병, 골연화증, 치아형성부전 등이 나타날 수 있으므로 관찰을 충분히 하고 이상(ALP, 혈청 칼슘 저하 및 무기인 저하 등)이 나타나는 경우에는 감량 또는 비타민D를 투여하는 등 적절히 조치한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (121, 49, '식약처_의약품허가', '포사맥스플러스디정 사용상의 주의사항 - 5. 상호작용(콜레칼시페롤)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200711426', NULL, NULL, '항경련제, 시메티딘, 치아자이드는 비타민 D의 이화작용을 증진시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (122, 49, '논문', 'Impact of carbamazepine on vitamin D levels: A meta-analysis (Epilepsy Res 2021)', 'https://pubmed.ncbi.nlm.nih.gov/34847425/', '34847425', NULL, 'The weighted difference of means was 4.00 ng/mL of 25OHD.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (123, 50, '식약처_의약품허가', '메가디쓰리정25000아이유(콜레칼시페롤농축분말) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201701511', NULL, NULL, '3) 글루코코르티코이드를 병용하면 비타민D의 효과를 감소시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (124, 50, '식약처_의약품허가', '네오칼시돌연질캡슐1마이크로그램(알파칼시돌) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202503410', NULL, NULL, '6) 페니토인과 글루코코르티코이드, 콜레스티폴, 수크랄페이트 또는 알루미늄이 다량 함유된 제산제를 복용 중인 환자(이 약의 작용을 억제할 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (125, 50, '논문', 'Association of glucocorticoid use and low 25-hydroxyvitamin D levels: results from NHANES 2001-2006 (J Clin Endocrinol Metab 2011)', 'https://pubmed.ncbi.nlm.nih.gov/21956424/', '21956424', NULL, 'Among steroid users, 11% had 25(OH)D levels below 10 ng/ml, compared to 5% among steroid nonusers (P = 0.009).', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (126, 51, '식약처_의약품허가', '네오반플러스정(발사르탄/히드로클로로티아지드) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200806640', NULL, NULL, '(9) 비타민 D : 티아지드계 이뇨제를 비타민 D 또는 칼슘염과 병용시 혈청 칼슘 수치를 증가시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (127, 51, '식약처_의약품허가', '메가디쓰리정25000아이유(콜레칼시페롤농축분말) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201701511', NULL, NULL, '고칼슘 혈증의 위험이 증가하기 때문에 혈청 칼슘은 티아지드계 이뇨제를 병용하는 동안 정기적으로 모니터링 해야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (128, 51, '식약처_의약품허가', '네오칼시돌연질캡슐1마이크로그램(알파칼시돌) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202503410', NULL, NULL, '3) 칼슘 함유제제 또는 치아지드계 이뇨제(고칼슘혈증의 위험이 증가한다.)', 'quote_ok');
