INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (130, 51, '식약처_의약품허가', '뉴알파정1마이크로그램(알파칼시돌) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202600653', NULL, NULL, '칼슘 함유제제 또는 치아지드계 이뇨제(고칼슘혈증의 위험이 증가한다.)', 'quote_ok');
