INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (133, 52, '논문', 'Calcium and calciferol antagonise effect of verapamil in atrial fibrillation (Br Med J 1981)', 'https://pubmed.ncbi.nlm.nih.gov/6786574/', '6786574', NULL, NULL, 'pmid_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (134, 53, '식약처_의약품허가', '렌벨라정(세벨라머탄산염) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201108203', NULL, NULL, '세벨라머를 투여하면서 별도로 비타민제를 복용하고 있지 않은 환자의 혈청 비타민 A, D, E, K의 상태를 정기적으로 평가하여야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (135, 54, '논문', 'Effects of vitamin D supplementation in atorvastatin-treated patients: a new drug interaction with an unexpected consequence (Clin Pharmacol Ther 2009)', 'https://pubmed.ncbi.nlm.nih.gov/18754003/', '18754003', NULL, 'Vitamin D supplementation increased vitamin D-25-OH metabolites (P < 0.0001) without increased 1,25-dihydroxy vitamin D.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (136, 55, '식약처_의약품허가', '메가디쓰리정25000아이유(콜레칼시페롤농축분말) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201701511', NULL, NULL, '2) 콜레스티라민과 같은 이온 교환 수지 또는 파라핀 오일과 같은 완하제의 동시투여는 비타민D의 위장흡수를 감소시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (137, 55, '식약처_의약품허가', '네오칼시돌연질캡슐1마이크로그램(알파칼시돌) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202503410', NULL, NULL, '5) 콜레스티라민 같은 수지나 사하제인 미네랄 오일을 복용 중인 환자(이 약의 장관흡수가 저하될 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (138, 56, '논문', 'Effect of isoniazid on vitamin D metabolism and hepatic monooxygenase activity (Clin Pharmacol Ther 1981)', 'https://pubmed.ncbi.nlm.nih.gov/7273600/', '7273600', NULL, '1 alpha-,25-dihydroxyvitamin D, the most active metabolite of vitamin D, fell by 47%', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (139, 57, '식약처_의약품허가', '그랑페롤연질캡슐400아이유(비타민이프리퍼레이션) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198700431', NULL, NULL, '5) 경구(먹는)용 항응고제를 복용 중인 환자(항응고제의 반응을 상승시킬 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (140, 57, '식약처_기타', '혈액순환 돕는 건강식품 섭취량 준수해야 (식품의약품안전청 보도자료, 2010.12.14, 정책브리핑)', 'https://www.korea.kr/news/policyNewsView.do?newsId=148703173', NULL, NULL, '또한 비타민 E는 와파린 등의 항혈액응고제, 비타민K, 에스트로젠이 포함된 경구용 피임약 등을 복용할 경우 반드시 섭취전에 의사나 약사와 미리 상의해야 한다.', 'skipped');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (141, 57, '논문', 'Vitamin E serum levels and bleeding risk in patients receiving oral anticoagulant therapy: a retrospective cohort study (J Am Heart Assoc 2013)', 'https://pubmed.ncbi.nlm.nih.gov/24166490/', '24166490', NULL, 'In a NVAF population being treated with warfarin, serum vitamin E predicted hemorrhagic events.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (142, 57, '논문', 'Effect of vitamin E on the anticoagulant response to warfarin (Am J Cardiol 1996)', 'https://pubmed.ncbi.nlm.nih.gov/8629604/', '8629604', NULL, 'None of the subjects who received vitamin E had a significant change in the international normalized ratio.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (143, 57, '논문', 'Coagulopathy associated with vitamin E ingestion (JAMA 1974)', 'https://pubmed.ncbi.nlm.nih.gov/4479598/', '4479598', NULL, NULL, 'pmid_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (144, 57, '논문', 'Effect of vitamin E supplementation on vitamin K status in adults with normal coagulation status (Am J Clin Nutr 2004)', 'https://pubmed.ncbi.nlm.nih.gov/15213041/', '15213041', NULL, 'High-dose vitamin E supplementation increased PIVKA-II in adults not receiving oral anticoagulant therapy.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (145, 58, '논문', 'A randomized trial of antioxidant vitamins to prevent second primary cancers in head and neck cancer patients (J Natl Cancer Inst 2005)', 'https://pubmed.ncbi.nlm.nih.gov/15812073/', '15812073', NULL, 'HR = 2.88, 95% CI = 1.56 to 5.31', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (146, 58, '논문', 'Randomized trial of antioxidant vitamins to prevent acute adverse effects of radiation therapy in head and neck cancer patients (J Clin Oncol 2005)', 'https://pubmed.ncbi.nlm.nih.gov/16027437/', '16027437', NULL, 'might compromise radiation treatment efficacy.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (147, 59, '논문', 'The effect of water-soluble vitamin E on cyclosporine pharmacokinetics in healthy volunteers (Clin Pharmacol Ther 1996)', 'https://pubmed.ncbi.nlm.nih.gov/8653992/', '8653992', NULL, 'The comparable relative decreases in apparent oral clearance (38%)', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (148, 59, '논문', 'Improvement of cyclosporin absorption in children after liver transplantation by means of water-soluble vitamin E (Lancet 1991)', 'https://pubmed.ncbi.nlm.nih.gov/1676779/', '1676779', NULL, 'Five responded; the oral cyclosporin dose could be reduced by 40-72% within 2 months.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (149, 60, '논문', 'Dietary supplement use during chemotherapy and survival outcomes of patients with breast cancer enrolled in a cooperative group clinical trial (SWOG S0221) (J Clin Oncol 2020)', 'https://pubmed.ncbi.nlm.nih.gov/31855498/', '31855498', NULL, 'associated with an increased hazard of recurrence (adjusted hazard ratio [adjHR], 1.41; 95% CI, 0.98 to 2.04', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (150, 61, '논문', 'Simvastatin and niacin, antioxidant vitamins, or the combination for the prevention of coronary disease (N Engl J Med 2001)', 'https://pubmed.ncbi.nlm.nih.gov/11757504/', '11757504', NULL, '21 percent in the antioxidant-therapy group; and 14 percent in the simvastatin-niacin-plus-antioxidants group.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (151, 61, '논문', 'Antioxidant supplements block the response of HDL to simvastatin-niacin therapy in patients with coronary artery disease and low HDL (Arterioscler Thromb Vasc Biol 2001)', 'https://pubmed.ncbi.nlm.nih.gov/11498460/', '11498460', NULL, 'increases in HDL-C, especially HDL(2)-C, were consistently higher in the S-N group than in the S-N+A group', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (152, 62, '논문', 'Increased tendency towards gingival bleeding caused by joint effect of alpha-tocopherol supplementation and acetylsalicylic acid (Ann Med 1998)', 'https://pubmed.ncbi.nlm.nih.gov/9920356/', '9920356', NULL, 'alpha-tocopherol supplementation may increase the risk of clinically important bleedings.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (153, 62, '논문', 'Effects of vitamin E on stroke subtypes: meta-analysis of randomised controlled trials (BMJ 2010)', 'https://pubmed.ncbi.nlm.nih.gov/21051774/', '21051774', NULL, 'the risk for haemorrhagic stroke was increased (pooled relative risk 1.22 (1.00 to 1.48), P=0.045)', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (154, 62, '논문', 'alpha-tocopherol inhibits aggregation of human platelets by a protein kinase C-dependent mechanism (Circulation 1996)', 'https://pubmed.ncbi.nlm.nih.gov/8921785/', '8921785', NULL, 'Platelet incorporation of alpha-tocopherol was associated with a significant reduction in platelet sensitivity', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (155, 62, '논문', 'Vitamin E plus aspirin compared with aspirin alone in patients with transient ischemic attacks (Am J Clin Nutr 1995)', 'https://pubmed.ncbi.nlm.nih.gov/7495235/', '7495235', NULL, 'There was no significant difference in the incidence of hemorrhagic stroke', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (156, 63, '식약처_의약품허가', '제니칼캡슐120밀리그램(오르리스타트) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200008801', NULL, NULL, '이 약은 또한 초산 비타민E 보충제의 흡수를 약 60 % 저해하였다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (157, 63, '식약처_의약품허가', '그랑페롤연질캡슐400아이유 사용상의 주의사항 - 3. 복용 전 상의할 것', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198700431', NULL, NULL, '6) 비만치료제(오르리스타트), 광유성 사하제(mineral oil)(기름성 설사약)를 복용 중인 환자(이 약의 흡수를 저해할 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (158, 63, '논문', 'Orlistat-associated adverse effects and drug interactions: a critical review (Drug Saf 2008)', 'https://pubmed.ncbi.nlm.nih.gov/18095746/', '18095746', NULL, 'Orlistat interferes with the absorption of many drugs (such as warfarin, amiodarone, ciclosporin and thyroxine as well as fat-soluble vitamins), affecting their bioavailability and effectiveness.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (159, 63, '논문', 'The effect of orlistat, an inhibitor of dietary fat absorption, on the absorption of vitamins A and E in healthy volunteers (J Clin Pharmacol 1996)', 'https://pubmed.ncbi.nlm.nih.gov/8844448/', '8844448', NULL, 'Orlistat significantly reduced the absorption of vitamin E (approximately 43% according to maximum concentration', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (160, 64, '식약처_의약품허가', '그랑페롤연질캡슐400아이유(비타민이프리퍼레이션) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198700431', NULL, NULL, '2) 에스트로겐이 포함된 경구(먹는)용 피임약을 복용하는 여성 또는 혈전(혈관 막힘)성 소인이 있는 환자[혈전(혈관 막힘)증 발생의 위험이 증가될 수 있다.]', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (161, 64, '식약처_기타', '혈액순환 돕는 건강식품 섭취량 준수해야 (식품의약품안전청 보도자료, 2010.12.14, 정책브리핑)', 'https://www.korea.kr/news/policyNewsView.do?newsId=148703173', NULL, NULL, '에스트로젠이 포함된 경구용피임약을 복용하는 여성의 경우 비타민 E가 피임약의 효능을 감소시킬 수 있다.', 'skipped');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (162, 65, '식약처_의약품허가', '그랑페롤연질캡슐400아이유(비타민이프리퍼레이션) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198700431', NULL, NULL, '6) 비만치료제(오르리스타트), 광유성 사하제(mineral oil)(기름성 설사약)를 복용 중인 환자(이 약의 흡수를 저해할 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (163, 66, '식약처_의약품허가', '쿠파린정5밀리그램(와파린나트륨) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200502107', NULL, NULL, '5) 다음 인자에 의해 이 약의 항응고 작용이 변화될 수 있다. : 비타민 K, 지방, 야채류 섭취, 신생아의 비타민 K 결핍, 비타민 C 결핍, 발열, 알코올 중독, X선 치료, 설사로 인한 비타민 K의 큰 손실 및 장에서의 소량 흡수', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (164, 66, '식약처_의약품허가', '제일와파린정(와파린나트륨) 사용상의 주의사항 - 4. 일반적 주의', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198500306', NULL, NULL, '5) 다음 인자에 의해 이 약의 항응고 작용이 변화될 수 있다. : 비타민 K, 지방, 야채류 섭취, 신생아의 비타민 K 결핍, 비타민 C 결핍, 발열, 알코올 중독, X선 치료, 설사로 인한 비타민 K의 큰 손실 및 장에서의 소량 흡수', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (165, 66, '식약처_건강기능식품', '「건강기능식품의 기준 및 규격」 일부개정고시(제2020-92호) - 식약처 수입식품정보마루 고시전문', 'https://impfood.mfds.go.kr/CFBDD02F02?active=00049&cntntsMngId1=00049&cntntsMngId2=00049&cntntsSn=326354', NULL, NULL, '베타카로틴, 비타민 K, 비타민 B1, 비타민 B2, 판토텐산, 비타민 B12, 비오틴, 칼륨, 크롬의 섭취 시 주의사항 마련 제안', 'skipped');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (166, 66, '식약처_건강기능식품', '「건강기능식품의 기준 및 규격」 일부개정고시(식약처 고시 제2020-92호, 2020.9.23.) 제3.1.1-5 비타민 K (3) 섭취 시 주의사항', 'https://www.mfds.go.kr/brd/m_207/down.do?brd_id=data0008&seq=14585&data_tp=A&file_seq=1', NULL, NULL, '(가) 항응고제 등 복용 시 전문가와 상담할 것', 'skipped');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (167, 66, '논문', 'Effect of vitamin K intake on the stability of oral anticoagulant treatment: dose-response relationships in healthy subjects (Blood 2004)', 'https://pubmed.ncbi.nlm.nih.gov/15231565/', '15231565', NULL, 'The threshold K(1) dose causing a statistically significant lowering of the INR was 150 microg/day.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (168, 66, '논문', 'Effect of low-dose supplements of menaquinone-7 (vitamin K2) on the stability of oral anticoagulant treatment (J Thromb Haemost 2013)', 'https://pubmed.ncbi.nlm.nih.gov/23530987/', '23530987', NULL, 'A daily intake of 45 μg of MK-7 significantly decreased the group mean values of both the INR and ucFII by ~ 40%.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (169, 66, '논문', 'Multivitamin supplements may affect warfarin anticoagulation in susceptible patients (Ann Pharmacother 2003)', 'https://pubmed.ncbi.nlm.nih.gov/14565795/', '14565795', NULL, 'Vitamin K(1) supplements of 25 microg daily are far below the dose thought to affect anticoagulant control.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (170, 67, '식약처_의약품허가', '경보세파클러캡슐 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200302420', NULL, NULL, '11) 비타민결핍증 : 드물게 비타민 K 결핍증상(저프로트롬빈혈증, 출혈경향 등), 비타민 B군 결핍증상(설염, 구내염, 식욕부진, 신경염 등)이 나타날 수 있다', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (171, 67, '식약처_의약품허가', '미노씬캡슐50mg(미노사이클린염산염) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198501028', NULL, NULL, '2) 고령자에서는 비타민 K 결핍에 의한 출혈 경향이 나타날 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (172, 67, '논문', 'Mechanism of cephalosporin-induced hypoprothrombinemia: relation to cephalosporin side chain, vitamin K metabolism, and vitamin K status (J Clin Pharmacol 1988)', 'https://pubmed.ncbi.nlm.nih.gov/3350995/', '3350995', NULL, 'NMTT-cephalosporins are inhibitors of hepatic vitamin K epoxide reductase.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (173, 68, '식약처_의약품허가', '제니칼캡슐120밀리그램(오르리스타트) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200008801', NULL, NULL, '따라서 이 약에 의해 비타민K 흡수가 감소될 수 있으므로, 안정된 용량의 와르파린을 장기간 복용중인 환자로서 이 약을 처방받은 환자는 혈액응고 계수의 변화를 면밀히 모니터링하여야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (174, 69, '논문', 'Vitamin K deficiency and bleeding after long-term use of cholestyramine (Neth J Med 2003)', 'https://pubmed.ncbi.nlm.nih.gov/12688565/', '12688565', NULL, 'who was on cholestyramine therapy for over 25 years before haemorrhage occurred.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (175, 69, '논문', 'To Take or Not to Take: A Case of Cholestyramine Induced Vitamin K Deficiency (S D Med 2025)', 'https://pubmed.ncbi.nlm.nih.gov/40878026/', '40878026', NULL, NULL, 'pmid_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (176, 70, '식약처_의약품허가', '하나페노바르비탈정 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197000212', NULL, NULL, '분만 전 산모(신생아 포함)에게 비타민 K1으로 예방적 치료가 권고되며, 신생아는 출혈의 징후에 대해 관찰되어야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (177, 71, '식약처_의약품허가', '유한메토트렉세이트정 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197900145', NULL, NULL, '엽산을 함유하는 비타민 제제 또는 엽산 유도체는 이 약의 효능을 감소시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (178, 71, '식약처_의약품허가', '일동폴산정1밀리그램 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201405494', NULL, NULL, '아미노살리실산, 경구용 피임제, 디하이드로폴레이트 환원효소 저해제(메토트렉세이트, 트리메토프림 등)를 복용 중인 환자(바람직하지 않는 상호작용을 초래할 수 있다)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (179, 71, '식약처_의약품허가', '유한메토트렉세이트정 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197900145', NULL, NULL, '5) 엽산을 함유하는 비타민 제제 또는 엽산 유도체는 이 약의 효능을 감소시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (180, 71, '논문', 'Folate Supplementation for Methotrexate Therapy in Patients With Rheumatoid Arthritis: A Systematic Review (J Clin Rheumatol 2019)', 'https://pubmed.ncbi.nlm.nih.gov/29975207/', '29975207', NULL, 'Folate supplementation can reduce the incidence of hepatotoxicity and gastrointestinal side-effects of MTX in patients with RA.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (181, 71, '논문', 'Folic acid and folinic acid for reducing side effects in patients receiving methotrexate for rheumatoid arthritis (Cochrane Database Syst Rev 2013)', 'https://europepmc.org/article/MED/23728635', '23728635', NULL, 'a 26% relative (9% absolute) risk reduction was seen for the incidence of GI side effects', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (182, 72, '식약처_의약품허가', '젤로다정500밀리그램(카페시타빈) 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200008797', NULL, NULL, '폴린산 : 카페시타빈과 폴린산의 병용연구에 따르면 폴린산은 카페시타빈의 약동학 및 그 대사체에 별다른 영향을 미치지 않으나 약력학에 영향을 미쳐 카페시타빈의 독성이 증가될 수 있다', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (183, 72, '논문', 'Intake and biomarkers of folate and folic acid as determinants of chemotherapy-induced toxicities in patients with colorectal cancer: a cohort study (Am J Clin Nutr 2024)', 'https://pubmed.ncbi.nlm.nih.gov/38070682/', '38070682', NULL, 'This study suggests a potential association between folic acid and capecitabine-induced toxicities', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (184, 73, '식약처_의약품허가', '부광페니토인캡슐100밀리그램 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197000104', NULL, NULL, '기타 : 결절성 동맥주위염, 다발성 관절증, 과혈당, 드물게 발열, 갑상샘기능검사치(혈청 T3, T4치 등)이상, 다모, 혈청엽산치 저하가 나타날 수 있다(경구제에 한함.).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (185, 73, '식약처_의약품허가', '하나페노바르비탈정 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197000212', NULL, NULL, '페노바르비탈을 투여받은 환자는 수정 전과 임신 중에 엽산을 충분히 보충해야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (186, 73, '식약처_의약품허가', '테그레톨정200밀리그램(카르바마제핀) 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200307816', NULL, NULL, '항뇌전증 약물은 엽산 결핍을 더 악화시키며, 이러한 결핍은 뇌전증치료를 받은 여성의 자식의 선천적 결함의 위험도를 더 증가 시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (187, 73, '식약처_의약품허가', '환인히단토인정(페니토인) 사용상의 주의사항 - 4. 이상반응', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197500285', NULL, NULL, '14) 기타 : 결절성 동맥주위염, 다발성 관절증, 과혈당, 드물게 발열, 갑상샘기능검사치(혈청 T3, T4치 등)이상, 다모, 혈청엽산치 저하가 나타날 수 있다(경구제에 한함.).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (188, 73, '식약처_의약품허가', '일동폴산정1밀리그램 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201405494', NULL, NULL, '페니토인 같은 히단토인계 항전간제를 복용 중인 환자(페니토인의 혈중농도를 감소시켜 발작빈도를 증가시킬 수 있다)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (189, 73, '논문', 'Phenytoin-folic acid interaction (Ann Pharmacother 1995)', 'https://pubmed.ncbi.nlm.nih.gov/8520091/', '8520091', NULL, 'Serum folate decreases when phenytoin therapy is initiated alone with no folate supplementation.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (190, 73, '논문', 'Phenytoin-folic acid interaction: a lesson to be learned (Clin Neuropharmacol 1999)', 'https://pubmed.ncbi.nlm.nih.gov/10516876/', '10516876', NULL, 'Folate supplementation of 5 mg/d was followed by a decrease of serum phenytoin concentration to a subtherapeutic level with a breakthrough seizure.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (191, 74, '식약처_의약품허가', '조피린장용정(설파살라진) 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199803482', NULL, NULL, '엽산과 병용투여 시 엽산의 흡수가 저하되고, 거대적혈모구증, 범혈구감소를 초래하는 엽산결핍증을 일으킬 수 있으므로 엽산결핍증이 의심되는 경우에는 엽산을 보충한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (192, 74, '식약처_의약품허가', '일동폴산정1밀리그램 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201405494', NULL, NULL, '설파살라진, 콜레스티라민을 복용 중인 환자(이 약의 위장관 흡수를 저해할 수 있다)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (193, 74, '논문', 'Sulfasalazine inhibits folate absorption (Nutr Rev 1988)', 'https://europepmc.org/article/MED/2906419', '2906419', NULL, NULL, 'pmid_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (194, 75, '식약처_의약품허가', '셉트린정 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197000049', NULL, NULL, '고령자, 폴산결핍증 환자 또는 신장애 환자에는 폴산결핍을 나타내는 혈액검사의 변화가 일어날 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (195, 75, '식약처_의약품허가', '일동폴산정1밀리그램 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201405494', NULL, NULL, '아미노살리실산, 경구용 피임제, 디하이드로폴레이트 환원효소 저해제(메토트렉세이트, 트리메토프림 등)를 복용 중인 환자(바람직하지 않는 상호작용을 초래할 수 있다)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (196, 75, '식약처_의약품허가', '셉트린정 사용상의 주의사항 - 5. 일반적 주의', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197000049', NULL, NULL, '14) 고령자, 폴산결핍증 환자 또는 신장애 환자에는 폴산결핍을 나타내는 혈액검사의 변화가 일어날 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (197, 76, '논문', 'A randomized controlled trial of folate supplementation when treating malaria in pregnancy with sulfadoxine-pyrimethamine (PLoS Clin Trials 2006)', 'https://europepmc.org/article/MED/17053829', '17053829', NULL, 'Concomitant use of 5 mg FA supplementation compromises the efficacy of SP', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (198, 76, '논문', 'Plasma folate levels and high-dose folate supplementation predict sulfadoxine-pyrimethamine treatment failure (J Infect Dis 2008)', 'https://europepmc.org/article/MED/18831691', '18831691', NULL, 'High-dose (5 mg daily) folate supplementation or high folate levels at day 7 were independent risk factors.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (199, 77, '식약처_의약품허가', '일동폴산정1밀리그램 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201405494', NULL, NULL, '설파살라진, 콜레스티라민을 복용 중인 환자(이 약의 위장관 흡수를 저해할 수 있다)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (200, 78, '식약처_의약품허가', '티비케이정50밀리그램(돌루테그라비르나트륨) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201404050', NULL, NULL, '마그네슘/알루미늄을 함유하는 제산제는 돌루테그라비르의 복용과 충분한 시간 간격을 두고 복용해야 한다(제산제 복용 2시간 전이나 6시간 후).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (201, 78, '식약처_의약품허가', '이센트레스정(랄테그라비르칼륨) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200806842', NULL, NULL, '그러므로, 이 약과 알루미늄 그리고/또는 마그네슘 함유 제산제와의 병용투여는 권장되지 않는다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (202, 78, '논문', 'Pharmacokinetics of the HIV integrase inhibitor S/GSK1349572 co-administered with acid-reducing agents and multivitamins in healthy volunteers (Patel, J Antimicrob Chemother 2011)', 'https://pubmed.ncbi.nlm.nih.gov/21493648/', '21493648', '10.1093/jac/dkr139', 'Concurrent antacid co-administration reduced S/GSK1349572 AUC by 74% and staggered antacid dosing significantly diminished this interaction', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (203, 79, '식약처_의약품허가', '아벨록스정400밀리그람(목시플록사신염산염) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199906848', NULL, NULL, '5) 제산제, 미네랄, 비타민 복합제 : 이 약과 제산제, 미네랄, 비타민 복합제를 병용 투여시 다가 양이온과 함께 킬레이트(chelate) 복합체를 형성하여 이 약의 흡수가 감소될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (204, 79, '식약처_의약품허가', '제일크라비트정(레보플록사신) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199400461', NULL, NULL, '2) 알루미늄 또는 마그네슘 함유 제산제, 수크랄페이트, 철분 함유 제제, 칼슘 함유 제제, 아연 또는 철분이 함유된 종합비타민제제와의 병용에 의해 흡수가 저하되어 효과가 저하되는 경우가 있으므로 이 약 투여 전후 2시간 이내에는 병용하지 않는 것이 바람직하다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (205, 79, '식약처_의약품허가', '크라비트정500밀리그람(레보플록사신) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200600109', NULL, NULL, '2) 알루미늄 또는 마그네슘 함유 제산제, 수크랄페이트, 철분 함유 제제, 칼슘 함유 제제, 아연 또는 철분이 함유된 종합비타민제제와의 병용에 의해 흡수가 저하되어 효과가 저하되는 경우가 있으므로 이 약 투여 전후 2시간 이내에는 병용하지 않는 것이 바람직하다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (206, 79, '식약처_의약품허가', '씨프로바이정250밀리그램(시프로플록사신염산염수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201905731', NULL, NULL, '3) 알루미늄 또는 마그네슘 함유 제산제와 같은 양이온 제제, 철분 함유 제제, 칼슘 함유 제제, 아연 또는 철분이 함유된 종합비타민제제, 포스페이트 결합제(예, 세벨라머, 탄산란탄), 수크랄페이트, 항레트로바이러스제, 디다노신과의 병용에 의해 이 약의 흡수가 저하되어 효과가 저하되는 경우가 있으므로 이 약 투여 전 1 ～ 2시간 및 투여 후 4시간 이내에는 병용하지 않는 것이 바람직하다(이 제한은 H2 길항제에는 적용되지 않는다).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (207, 79, '논문', 'Effects of aluminum and magnesium antacids and ranitidine on the absorption of ciprofloxacin (Nix, Clin Pharmacol Ther 1989)', 'https://pubmed.ncbi.nlm.nih.gov/2598571/', '2598571', '10.1038/clpt.1989.207', 'Administration of antacid within 4 hours before ciprofloxacin dose resulted in a significant decrease in ciprofloxacin absorption (p less than 0.05).', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (208, 80, '식약처_의약품허가', '레볼레이드정25밀리그램(엘트롬보팍올라민) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201002060', NULL, NULL, '임상시험에서, 다가 양이온 함유 제산제(1,524mg 수산화알루미늄, 1,425mg 탄산마그네슘 및 알긴산 나트륨)와 이 약의 병용투여가 혈장 엘트롬보팍 전신 노출을 약 70%까지 감소시켰다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (209, 80, '논문', 'Effects of food and antacids on the pharmacokinetics of eltrombopag in healthy adult subjects (Williams, Clin Ther 2009)', 'https://pubmed.ncbi.nlm.nih.gov/19446149/', '19446149', '10.1016/j.clinthera.2009.04.010', 'Mean plasma AUC(0-infinity)) and C(max) values decreased by approximately 70%', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (210, 81, '식약처_의약품허가', '로칼트롤연질캡슐0.25마이크로그람(칼시트리올) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200610653', NULL, NULL, '6) 장기 신장투석 환자의 경우 마그네슘 함유제제(제산제, 사하제)와의 병용에 의해 고마그네슘혈증이 나타날 수 있으므로, 이 약의 투여기간 동안에는 병용하지 않는다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (211, 81, '식약처_의약품허가', '원알파정(알파칼시돌) 사용상의 주의사항 - 2. 이 약을 복용하는 동안 다음의 약을 복용하지 말 것.', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199001232', NULL, NULL, '1) 마그네슘 함유제제(고마그네슘혈증이 나타날 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (212, 82, '식약처_의약품허가', '뉴론틴캡슐300밀리그램(가바펜틴) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200511066', NULL, NULL, '5) 알루미늄·마그네슘 복합 제산제와 이 약의 병용투여는 가바펜틴의 생체이용율을 약 20% 정도 감소시킨다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (213, 82, '논문', 'Impact of concomitant antacid administration on gabapentin plasma exposure and oral bioavailability in healthy adult subjects (Yagi, Drug Metab Pharmacokinet 2012)', 'https://pubmed.ncbi.nlm.nih.gov/22240839/', '22240839', '10.2133/dmpk.dmpk-11-rg-108', 'concomitant MgO decreased the gabapentin exposure through the reduction of intestinal absorption extent and rate.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (214, 83, '식약처_의약품허가', '독시마이신엔정100mg(독시사이클린수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201802879', NULL, NULL, '3) 칼슘, 마그네슘, 알루미늄을 함유하는 제산제 또는 이들 양이온을 함유하는 다른 약물들, 철·아연을 함유하고 있는 제제와 약용탄, 카올린, 펙틴 또는 비스무트(bismuth)염 제제에 의해 테트라사이클린계 약물의 흡수가 저하되어 효과가 저하될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (215, 83, '식약처_의약품허가', '마그밀정(수산화마그네슘) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197400246', NULL, NULL, '1) 테트라사이클린계 항생물질의 흡수를 저해할 수 있으므로 병용투여하지 않는다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (216, 83, '식약처_의약품허가', '미노씬캡슐50mg(미노사이클린염산염) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198501028', NULL, NULL, '4) 칼슘, 마그네슘, 알루미늄을 함유하는 제산제 또는 이들 양이온을 함유하는 다른 약물들, 철ㆍ아연을 함유하고 있는 제제와 약용탄, 카올린, 펙틴 또는 비스무스(bismuth)염 제제에 의해 테트라사이클린계 약물의 흡수가 저하되어 효과가 저하될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (217, 83, '논문', 'Interactions with the absorption of tetracyclines (Neuvonen, Drugs 1976)', 'https://pubmed.ncbi.nlm.nih.gov/946598/', '946598', '10.2165/00003495-197611010-00004', 'Tetracyclines have a high affinity to form chelates with polyvalent metallic cations such as Fe+++, Fe++, Al+++, Mg++ and Ca++.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (218, 84, '논문', 'Intestinal adsorption of levothyroxine by antacids and laxatives: case stories and in vitro experiments (Mersebach, Pharmacol Toxicol 1999)', 'https://pubmed.ncbi.nlm.nih.gov/10193669/', '10193669', '10.1111/j.1600-0773.1999.tb00883.x', 'consumption of antacids/laxatives in patients with levothyroxine-treated hypothyroidism may lead to serious undersubstitution with levothyroxine.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (219, 85, '식약처_의약품허가', '악토넬정35밀리그람 사용상의 주의사항 - 5. 일반적 주의', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200200772', NULL, NULL, '(1) 다가 양이온(칼슘, 마그네슘, 철, 알루미늄 등)을 함유한 약물, 식품, 순수한 물 이외의 음료수는 이 약의 흡수를 방해할 수 있기 때문에 동시에 투여하지 말아야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (220, 86, '식약처_의약품허가', '셀셉트캡슐250밀리그램(미코페놀레이트모페틸) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200610652', NULL, NULL, '3) 제산제 및 프로톤펌프억제제(PPIs) : 제산제(수산화 마그네슘, 수산화 알루미늄 등) 및 프로톤펌프억제제(란소프라졸, 판토프라졸 포함)와 병용투여 시 미코페놀산의 노출이 감소되었다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (221, 87, '식약처_의약품허가', '본비바정150밀리그램(이반드론산나트륨일수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200607634', NULL, NULL, '2) 칼슘보조제, 제산제, 다가 양이온(알루미늄, 마그네슘, 철)을 포함한 경구투여 약물은 이 약의 흡수를 저해할 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (222, 87, '식약처_의약품허가', '악토넬정35밀리그람(리세드론산나트륨) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200200772', NULL, NULL, '(1) 다가 양이온(칼슘, 마그네슘, 철, 알루미늄 등)을 함유한 약물, 식품, 순수한 물 이외의 음료수는 이 약의 흡수를 방해할 수 있기 때문에 동시에 투여하지 말아야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (223, 88, '식약처_의약품허가', '뉴알파정1마이크로그램(알파칼시돌) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202600653', NULL, NULL, '마그네슘 함유제제(고마그네슘혈증이 나타날 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (224, 89, '식약처_의약품허가', '넥시움정20밀리그램(에스오메프라졸마그네슘) 사용상의 주의사항 - 3. 일반적 주의', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200009027', NULL, NULL, '8) 3개월 이상 프로톤펌프억제제(Proton Pump Inhibitor) 치료를 받은 환자들에게서 저마그네슘혈증이 드물게 보고되었으며, 1년 이상 치료를 받은 경우에 가장 많이 나타났다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (225, 89, '식약처_의약품허가', '란스톤캡슐15밀리그램(란소프라졸과립) 사용상의 주의사항 - 4. 일반적 주의', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200210756', NULL, NULL, '장기간 치료가 필요하거나 디곡신 또는 저마그네슘혈증을 유발하는 약물(예, 이뇨제)을 병용투여하는 환자들은 치료 시작을 포함한 주기적 마그네슘 수치 모니터링이 필요하다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (226, 89, '논문', 'Proton pump inhibitors linked to hypomagnesemia: a systematic review and meta-analysis of observational studies (Ren Fail 2015)', 'https://pubmed.ncbi.nlm.nih.gov/26108134/', '26108134', NULL, 'The pooled RR of hypomagnesemia in patients with PPI use was 1.43 (95% CI, 1.08-1.88).', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (227, 90, '식약처_의약품허가', '알타민캡슐250밀리그램(디-페니실라민) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198300142', NULL, NULL, '3) 경구철제제(구연산제일철나트륨, 황산철 등), 마그네슘 또는 알루미늄 함유제산제(수산화마그네슘, 수산화알루미늄)는 이 약의 흡수율을 저하시켜 효과를 감소시킬 수 있으므로, 반드시 투여해야 하는 경우에는 동시투여를 피한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (228, 90, '논문', 'Reduction in oral penicillamine absorption by food, antacid, and ferrous sulfate (Osman, Clin Pharmacol Ther 1983)', 'https://pubmed.ncbi.nlm.nih.gov/6831825/', '6831825', '10.1038/clpt.1983.63', 'Penicillamine levels were reduced to 52%, 35%, and 66% of those from the fasting dose after food, ferrous sulfate, and antacid.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (229, 91, '식약처_의약품허가', '크레스토정10밀리그램(로수바스타틴칼슘) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200210097', NULL, NULL, '제산제 : 수산화알루미늄, 수산화마그네슘을 함유하는 제산제와 이 약을 병용 투여한 결과, 로수바스타틴의 혈장 농도가 약 50% 감소되었다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (230, 92, '식약처_의약품허가', '에스메론주(로쿠로늄브롬화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200903088', NULL, NULL, '주의 2: 마그네슘염은 신경근 차단에 대해 상승 작용을 일으키므로 임신 중독증으로 마그네슘염을 투여 받는 환자의 경우에는 신경근 차단제 투여 후 신경근 회복이 억제되거나 불완전할 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (231, 93, '식약처_의약품허가', '세프다나캡슐100밀리그램(세프디니르) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200711458', NULL, NULL, '3)제산제(알루미늄 또는 마그네슘 함유)와 함께 복용하면 이 약의 흡수를 저하시켜, 효과를 감소시킬 수 있으므로 이 약의 투여후 2시간 이상 간격을 두고 투여한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (232, 94, '식약처_의약품허가', '레볼레이드정25밀리그램(엘트롬보팍올라민) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201002060', NULL, NULL, '4) 다가 양이온(킬레이트화): 엘트롬보팍은 음식물, 미네랄 보충제 및 제산제 내의 철분, 칼슘, 알루미늄, 마그네슘, 셀레늄, 아연과 같은 다가 양이온을 킬레이트화한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (233, 95, '식약처_의약품허가', '티비케이정50밀리그램(돌루테그라비르나트륨) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201404050', NULL, NULL, '종합비타민제 복용과 충분한 시간 간격을 두고 복용해야 한다(종합비타민제 복용 최소한 2시간 전이나 6시간 후).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (234, 95, '식약처_의약품허가', '젠보야정 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201605531', NULL, NULL, '이 약과 다가 양이온을 함유한 제산제, 의약품 또는 경구용 보충제의 투여간 시간 간격을 최소 4 시간 분리하는 것이 권장됨.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (235, 95, '논문', 'Pharmacokinetics of the HIV integrase inhibitor S/GSK1349572 co-administered with acid-reducing agents and multivitamins in healthy volunteers (Patel, J Antimicrob Chemother 2011)', 'https://pubmed.ncbi.nlm.nih.gov/21493648/', '21493648', '10.1093/jac/dkr139', 'MVI co-administration modestly decreased S/GSK1349572 AUC by 33%.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (236, 96, '식약처_의약품허가', '씨프로바이정250밀리그램 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201905731', NULL, NULL, '3) 알루미늄 또는 마그네슘 함유 제산제와 같은 양이온 제제, 철분 함유 제제, 칼슘 함유 제제, 아연 또는 철분이 함유된 종합비타민제제, 포스페이트 결합제(예, 세벨라머, 탄산란탄), 수크랄페이트, 항레트로바이러스제, 디다노신과의 병용에 의해 이 약의 흡수가 저하되어 효과가 저하되는 경우가 있으므로 이 약 투여 전 1 ～ 2시간 및 투여 후 4시간 이내에는 병용하지 않는 것이 바람직하다(이 제한은 H2 길항제에는 적용되지 않는다).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (237, 96, '논문', 'Effect of ferrous sulfate and multivitamins with zinc on absorption of ciprofloxacin in normal volunteers (Antimicrob Agents Chemother 1989)', 'https://pubmed.ncbi.nlm.nih.gov/2610494/', '2610494', NULL, 'Ferrous sulfate and multivitamins with zinc significantly impaired the absorption of ciprofloxacin.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (238, 97, '식약처_의약품허가', '레볼레이드정25밀리그램(엘트롬보팍올라민) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201002060', NULL, NULL, '4) 다가 양이온(킬레이트화): 엘트롬보팍은 음식물, 미네랄 보충제 및 제산제 내의 철분, 칼슘, 알루미늄, 마그네슘, 셀레늄, 아연과 같은 다가 양이온을 킬레이트화한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (239, 98, '식약처_의약품허가', '알타민캡슐250밀리그램(디-페니실라민) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198300142', NULL, NULL, '4) 아연을 함유하는 경구제는 이 약의 효과를 감소시킬 수 있으므로, 반드시 병용해야 하는 경우에는 동시투여를 피한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (240, 98, '논문', 'Treatment of Wilson''s disease with zinc: XI. Interaction with other anticopper agents (Brewer, J Am Coll Nutr 1993)', 'https://pubmed.ncbi.nlm.nih.gov/8440814/', '8440814', '10.1080/07315724.1993.10718278', 'We find evidence for probable interactions of both penicillamine and trien with Zn', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (241, 99, '식약처_의약품허가', '국제독시사이클린하이클레이트수화물캡슐100밀리그램 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198000105', NULL, NULL, '3) 칼슘, 마그네슘, 알루미늄을 함유하는 제산제 또는 이들 양이온을 함유하는 다른 약물들, 철ㆍ아연을 함유하고 있는 제제와 약용탄, 카올린, 펙틴 또는 비스무트(bismuth)염 제제에 의해 테트라사이클린계 약물의 흡수가 저하되어 효과가 저하될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (242, 99, '식약처_의약품허가', '독시마이신엔정100mg(독시사이클린수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201802879', NULL, NULL, '3) 칼슘, 마그네슘, 알루미늄을 함유하는 제산제 또는 이들 양이온을 함유하는 다른 약물들, 철·아연을 함유하고 있는 제제와 약용탄, 카올린, 펙틴 또는 비스무트(bismuth)염 제제에 의해 테트라사이클린계 약물의 흡수가 저하되어 효과가 저하될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (243, 99, '식약처_의약품허가', '라이트징크시럽(황산아연일수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201206329', NULL, NULL, '2) 이 약을 투여할 경우에는 인산염, 칼슘염, 경구용테트라사이클린계 제제, 제산제와 병용투여하지 않는다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (244, 99, '논문', 'Effect of zinc sulphate on the absorption of tetracycline and doxycycline in man (Penttilä, Eur J Clin Pharmacol 1975)', 'https://pubmed.ncbi.nlm.nih.gov/786686/', '786686', '10.1007/BF00614009', 'The absorption of doxycycline was not influenced significantly by zinc sulphate.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (245, 100, '식약처_의약품허가', '치오단정130밀리그램(요오드화칼륨) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201102783', NULL, NULL, '1) 리튬제제 병용에 의하여 갑상선기능저하작용, 갑상선종 발현 작용을 증대시킬 수 있으므로 뇌하수체 갑상선 반응의 변화, 갑상선 기능측정 등을 실시하여 신중히 투여한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (246, 100, '논문', 'Effect of increased iodide intake on thyroid function in subjects on chronic lithium therapy (Spaulding, Acta Endocrinol 1977)', 'https://pubmed.ncbi.nlm.nih.gov/576345/', '576345', '10.1530/acta.0.0840290', 'Pharmacologic doses of iodine should be administered with caution to patients on chronic lithium therapy.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (247, 101, '논문', 'Effects of chronic iodine administration on thyroid status in euthyroid subjects previously treated with antithyroid drugs for Graves'' hyperthyroidism (Roti, J Clin Endocrinol Metab 1993)', 'https://pubmed.ncbi.nlm.nih.gov/7682562/', '7682562', '10.1210/jcem.76.4.7682562', '2 women developed overt hyperthyroidism, with undetectable basal and TRH-stimulated serum TSH and elevated serum T4 and T3 concentrations, requiring methimazole therapy.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (248, 102, '식약처_의약품허가', '치오단정130밀리그램(요오드화칼륨) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201102783', NULL, NULL, '3) 131I 요법을 행하는 경우에는 그 1주일 전에 복용을 중지한다(요오드화칼륨의 요오드는 131 I의 섭취율을 저하시킬 수 있다.).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (249, 103, '식약처_의약품허가', '코다론정(아미오다론염산염) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200701021', NULL, NULL, '이 약은 특히 갑상선질환의 병력 및 가족력이 있는 환자에게 갑상선기능항진증 또는 갑상선기능저하증을 야기할 수 있으므로 이 약 투여 전에 임상적 및 생리학적(usTSH) 모니터링이 권장된다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (250, 103, '논문', 'Amiodarone and the thyroid (Basaria & Cooper, Am J Med 2005)', 'https://pubmed.ncbi.nlm.nih.gov/15989900/', '15989900', '10.1016/j.amjmed.2004.11.028', 'Amiodarone-induced thyroid dysfunction occurs because of both its iodine content and the direct toxic effects of the compound on thyroid parenchyma.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (251, 104, '식약처_의약품허가', '티비케이정50밀리그램(돌루테그라비르나트륨) 사용상의 주의사항 - 5. 상호작용(표)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201404050', NULL, NULL, '칼슘 보충제, 철분 보충제는 돌루테그라비르의 복용과 충분한 시간 간격을 두고 복용해야 한다(칼슘 또는 철분 보충제 복용 2시간 전이나 6시간 후).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (252, 104, '식약처_의약품허가', '빅타비정 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201900267', NULL, NULL, '이 약은 철분 함유 경구용 약물이나 보충제 투여 최소 2시간 이전 또는 6시간 이후에 투여해야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (253, 104, '논문', 'Pharmacokinetics of dolutegravir when administered with mineral supplements in healthy adult subjects (J Clin Pharmacol 2015)', 'https://pubmed.ncbi.nlm.nih.gov/25449994/', '25449994', NULL, 'Under fasted conditions, dolutegravir should be administered 2 hours before or 6 hours after calcium or iron supplements.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (254, 105, '식약처_의약품허가', '빅타비정 사용상의 주의사항 - 1. 경고', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201900267', NULL, NULL, '이 약을 철분 보충제와 함께 투여할 때에는, 이 약을 최소 2시간 전에 복용하거나 또는 어느때라도 음식과 함께 투여해야 한다(사용상의 주의사항 중 ‘5. 약물 상호작용’ 참조).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (255, 105, '논문', 'The effect of antacid and mineral supplements on bictegravir pharmacokinetics: Phase 1 drug-drug interaction study (Antimicrob Agents Chemother 2026)', 'https://pubmed.ncbi.nlm.nih.gov/41313173/', '41313173', NULL, NULL, 'pmid_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (256, 106, '식약처_의약품허가', '씨프로바이정250밀리그램 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201905731', NULL, NULL, '3) 알루미늄 또는 마그네슘 함유 제산제와 같은 양이온 제제, 철분 함유 제제, 칼슘 함유 제제, 아연 또는 철분이 함유된 종합비타민제제, 포스페이트 결합제(예, 세벨라머, 탄산란탄), 수크랄페이트, 항레트로바이러스제, 디다노신과의 병용에 의해 이 약의 흡수가 저하되어 효과가 저하되는 경우가 있으므로 이 약 투여 전 1 ～ 2시간 및 투여 후 4시간 이내에는 병용하지 않는 것이 바람직하다(이 제한은 H2 길항제에는 적용되지 않는다).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (257, 106, '식약처_의약품허가', '아벨록스정400밀리그람(목시플록사신염산염) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199906848', NULL, NULL, '5) 제산제, 미네랄, 비타민 복합제 : 이 약과 제산제, 미네랄, 비타민 복합제를 병용 투여시 다가 양이온과 함께 킬레이트(chelate) 복합체를 형성하여 이 약의 흡수가 감소될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (258, 106, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '12) 퀴놀론계, 페니실라민, 콜레스티라민, 췌장엑스 및 비타민 E와 같은 제제를 복용중인 사람', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (259, 106, '논문', 'Effect of ferrous sulfate and multivitamins with zinc on absorption of ciprofloxacin in normal volunteers (Antimicrob Agents Chemother 1989)', 'https://pubmed.ncbi.nlm.nih.gov/2610494/', '2610494', NULL, 'Ferrous sulfate and multivitamins with zinc significantly impaired the absorption of ciprofloxacin.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (260, 107, '식약처_의약품허가', '국제독시사이클린하이클레이트수화물캡슐100밀리그램 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198000105', NULL, NULL, '3) 칼슘, 마그네슘, 알루미늄을 함유하는 제산제 또는 이들 양이온을 함유하는 다른 약물들, 철ㆍ아연을 함유하고 있는 제제와 약용탄, 카올린, 펙틴 또는 비스무트(bismuth)염 제제에 의해 테트라사이클린계 약물의 흡수가 저하되어 효과가 저하될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (261, 107, '식약처_의약품허가', '미노씬캡슐50mg(미노사이클린염산염) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198501028', NULL, NULL, '양이온 함유 약물과 병용투여 하는 경우에는 테트라사이클린계 약물의 흡수가 저하되므로 2시간 이상의 간격을 두고 투여한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (262, 107, '식약처_의약품허가', '독시마이신엔정100mg(독시사이클린수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201802879', NULL, NULL, '3) 칼슘, 마그네슘, 알루미늄을 함유하는 제산제 또는 이들 양이온을 함유하는 다른 약물들, 철·아연을 함유하고 있는 제제와 약용탄, 카올린, 펙틴 또는 비스무트(bismuth)염 제제에 의해 테트라사이클린계 약물의 흡수가 저하되어 효과가 저하될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (263, 107, '식약처_의약품허가', '엘레비트정 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201602683', NULL, NULL, '1) 테트라사이클린류: 흡수방해의 상호작용 가능성 때문에 철분을 포함하는 약물은 테트라사이클린류와의 병용을 피해야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (264, 107, '논문', 'Inhibitory effect of various iron salts on the absorption of tetracycline in man (Eur J Clin Pharmacol 1974)', 'https://pubmed.ncbi.nlm.nih.gov/4213690/', '4213690', NULL, NULL, 'pmid_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (265, 107, '논문', 'Interference of iron with the absorption of tetracyclines in man (Neuvonen, BMJ 1970)', 'https://pubmed.ncbi.nlm.nih.gov/5483323/', '5483323', '10.1136/bmj.4.5734.532', 'Ferrous sulphate administered together with tetracycline and three of its derivatives-oxytetracycline, methacycline, and doxycycline-was found seriously to impair the absorption of these antibiotics.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (266, 107, '논문', 'Interactions with the absorption of tetracyclines (Neuvonen, Drugs 1976)', 'https://pubmed.ncbi.nlm.nih.gov/946598/', '946598', '10.2165/00003495-197611010-00004', 'An interval of 3 hours between the ingestion of tetracyclines and cations prevents the interaction.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (267, 108, '식약처_의약품허가', '마도파에취비에스캡슐125 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199203393', NULL, NULL, '10) 황산 제1철은 레보도파의 최대 혈장 농도와 혈중 곡선하 면적을 30-50% 감소시킨다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (268, 108, '식약처_의약품허가', '퍼킨씨알정50-200밀리그램(카르비도파, 레보도파) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201907607', NULL, NULL, '6) 철분염: 황산철 또는 글루콘산철과 병용투여시 킬레이트를 형성하여 카르비도파 및 레보도파의 생체내 이용률이 저하된다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (269, 108, '식약처_의약품허가', '명도파정25/100밀리그램(벤세라지드, 레보도파) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202104353', NULL, NULL, '10) 황산 제1철은 레보도파의 최대 혈장 농도와 혈중 곡선하 면적을 30-50% 감소시킨다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (270, 108, '논문', 'Ferrous sulfate reduces levodopa bioavailability: chelation as a possible mechanism (Clin Pharmacol Ther 1989)', 'https://pubmed.ncbi.nlm.nih.gov/2920496/', '2920496', NULL, 'Chelation of iron by levodopa is the likely mechanism for this drug interaction.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (271, 108, '논문', 'Sinemet-ferrous sulphate interaction in patients with Parkinson''s disease (Campbell, Br J Clin Pharmacol 1990)', 'https://pubmed.ncbi.nlm.nih.gov/2291872/', '2291872', '10.1111/j.1365-2125.1990.tb03819.x', 'Ferrous sulphate ingestion with Sinemet resulted in a decrease in levodopa area under the curve (AUC) of 30% (P less than 0.01)', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (272, 109, '식약처_의약품허가', '씬지로이드정0.05밀리그램 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200401821', NULL, NULL, '5) 콜레스티라민, 철분제제, 알루미늄 함유 제산제와 병용투여시 이 약의 흡수가 지연 또는 감소될 수 있으므로 투여간격에 주의하며 신중히 투여한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (273, 109, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '철분 제제와 디포스폰산 염류, 티록신, 세프디니르 제제를 동시 복용하는 사람(이 제제들의 흡수가 감소되므로 일정한 시간간격 (2～3시간 이상)을 두고 복용할 것.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (274, 109, '식약처_의약품허가', '씬지로이드정0.1밀리그램(레보티록신나트륨수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197400278', NULL, NULL, '5) 콜레스티라민, 철분제제, 알루미늄 함유 제산제와 병용투여시 이 약의 흡수가 지연 또는 감소될 수 있으므로 투여간격에 주의하며 신중히 투여한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (275, 109, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '10) 철분 제제와 디포스폰산 염류, 티록신, 세프디니르 제제를 동시 복용하는 사람(이 제제들의 흡수가 감소되므로 일정한 시간간격 (2～3시간 이상)을 두고 복용할 것.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (276, 109, '식약처_기타', '의약품 복용 시 주의해야 할 식품 (식품의약품안전처 작성, 정책브리핑 게재 2022.05.17)', 'https://www.korea.kr/news/healthView.do?newsId=148901697', NULL, NULL, '칼슘이나 철 보충제, 콩 식품은 약의 흡수를 방해하므로 약 복용 후, 4시간 후에 섭취한다.', 'skipped');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (277, 109, '논문', 'Ferrous sulfate reduces thyroxine efficacy in patients with hypothyroidism (Ann Intern Med 1992)', 'https://pubmed.ncbi.nlm.nih.gov/1443969/', '1443969', NULL, 'Simultaneous ingestion of ferrous sulfate and thyroxine causes a variable reduction in thyroxine efficacy that is clinically significant in some patients.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (278, 110, '식약처_의약품허가', '악토넬정35밀리그람(리세드론산나트륨) 사용상의 주의사항 - 5. 일반적 주의', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200200772', NULL, NULL, '(1) 다가 양이온(칼슘, 마그네슘, 철, 알루미늄 등)을 함유한 약물, 식품, 순수한 물 이외의 음료수는 이 약의 흡수를 방해할 수 있기 때문에 동시에 투여하지 말아야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (279, 110, '식약처_의약품허가', '본비바정150밀리그램 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200607634', NULL, NULL, '2) 칼슘보조제, 제산제, 다가 양이온(알루미늄, 마그네슘, 철)을 포함한 경구투여 약물은 이 약의 흡수를 저해할 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (280, 111, '식약처_의약품허가', '신풍메틸도파정(수출용) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200804297', NULL, NULL, '4) 철과 병용투여하는 경우에는 이 약의 흡수가 저해될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (281, 111, '논문', 'Alteration of methyldopa absorption, metabolism, and blood pressure control caused by ferrous sulfate and ferrous gluconate (Campbell, Clin Pharmacol Ther 1988)', 'https://pubmed.ncbi.nlm.nih.gov/3356082/', '3356082', '10.1038/clpt.1988.47', 'These factors resulted in an 88% reduction in the quantity of "free" methyldopa excreted.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (282, 112, '식약처_의약품허가', '옴니세프캡슐100밀리그램(세프디니르) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199800677', NULL, NULL, '1) 철분제제와 함께 복용하면 이 약의 흡수를 약 1/10까지 저해하므로 함께 복용하지 않는 것이 좋다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (283, 112, '식약처_의약품허가', '세프다나캡슐100밀리그램(세프디니르) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200711458', NULL, NULL, '1) 철분제제와 함께 복용하면 이 약의 흡수를 약 1/10까지 저해하므로 함께 복용하지 않는 것이 좋다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (284, 112, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '10) 철분 제제와 디포스폰산 염류, 티록신, 세프디니르 제제를 동시 복용하는 사람(이 제제들의 흡수가 감소되므로 일정한 시간간격 (2～3시간 이상)을 두고 복용할 것.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (285, 112, '논문', 'Impairment of cefdinir absorption by iron ion (Clin Pharmacol Ther 1993)', 'https://pubmed.ncbi.nlm.nih.gov/8222489/', '8222489', NULL, 'These findings suggest that the mechanism of interaction between cefdinir and iron ion preparation is the formation of a chelation complex', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (286, 113, '식약처_의약품허가', '악토넬정35밀리그람(리세드론산나트륨) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200200772', NULL, NULL, '(1) 다가 양이온(칼슘, 마그네슘, 철, 알루미늄 등)을 함유한 약물, 식품, 순수한 물 이외의 음료수는 이 약의 흡수를 방해할 수 있기 때문에 동시에 투여하지 말아야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (287, 113, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '10) 철분 제제와 디포스폰산 염류, 티록신, 세프디니르 제제를 동시 복용하는 사람(이 제제들의 흡수가 감소되므로 일정한 시간간격 (2～3시간 이상)을 두고 복용할 것.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (288, 114, '논문', 'Proton pump inhibitors suppress absorption of dietary non-haem iron in hereditary haemochromatosis (Hutchinson, Gut 2007)', 'https://pubmed.ncbi.nlm.nih.gov/17344278/', '17344278', '10.1136/gut.2006.108613', 'Administration of a PPI to patients with HH can inhibit the absorption of non-haem iron from a test meal and the habitual diet.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (289, 114, '논문', 'Proton Pump Inhibitor and Histamine-2 Receptor Antagonist Use and Iron Deficiency (Lam, Gastroenterology 2017)', 'https://pubmed.ncbi.nlm.nih.gov/27890768/', '27890768', '10.1053/j.gastro.2016.11.023', 'gastric acid inhibitor use for ≥2 years was associated with an increased subsequent risk of iron deficiency.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (290, 115, '식약처_의약품허가', '레볼레이드정25밀리그램(엘트롬보팍올라민) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201002060', NULL, NULL, '4) 다가 양이온(킬레이트화): 엘트롬보팍은 음식물, 미네랄 보충제 및 제산제 내의 철분, 칼슘, 알루미늄, 마그네슘, 셀레늄, 아연과 같은 다가 양이온을 킬레이트화한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (291, 115, '논문', 'Effects of food and antacids on the pharmacokinetics of eltrombopag in healthy adult subjects (Williams, Clin Ther 2009)', 'https://pubmed.ncbi.nlm.nih.gov/19446149/', '19446149', '10.1016/j.clinthera.2009.04.010', 'Mean plasma AUC(0-infinity)) and C(max) values decreased by approximately 70%', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (292, 116, '식약처_의약품허가', '알타민캡슐250밀리그램(디-페니실라민) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198300142', NULL, NULL, '3) 경구철제제(구연산제일철나트륨, 황산철 등), 마그네슘 또는 알루미늄 함유제산제(수산화마그네슘, 수산화알루미늄)는 이 약의 흡수율을 저하시켜 효과를 감소시킬 수 있으므로, 반드시 투여해야 하는 경우에는 동시투여를 피한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (293, 116, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '12) 퀴놀론계, 페니실라민, 콜레스티라민, 췌장엑스 및 비타민 E와 같은 제제를 복용중인 사람', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (294, 116, '논문', 'Reduction in oral penicillamine absorption by food, antacid, and ferrous sulfate (Clin Pharmacol Ther 1983)', 'https://pubmed.ncbi.nlm.nih.gov/6831825/', '6831825', NULL, 'Penicillamine levels were reduced to 52%, 35%, and 66% of those from the fasting dose after food, ferrous sulfate, and antacid.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (295, 117, '식약처_의약품허가', '란스톤캡슐15밀리그램(란소프라졸과립) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200210756', NULL, NULL, '다른 산 분비 억제제나 제산제와 마찬가지로 이 약 투여 중에는 케토코나졸, 이트라코나졸, 암피실린에스테르, 아타자나비어, 철염, 엘로티닙, 게피티니브 및 미코페놀레이트 모페틸의 흡수가 감소될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (296, 117, '논문', 'Proton pump inhibitors suppress absorption of dietary non-haem iron in hereditary haemochromatosis (Gut 2007)', 'https://pubmed.ncbi.nlm.nih.gov/17344278/', '17344278', NULL, 'Administration of a PPI to patients with HH can inhibit the absorption of non-haem iron from a test meal and the habitual diet.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (297, 118, '논문', 'Impairment of mycophenolate mofetil absorption by iron ion (Morii, Clin Pharmacol Ther 2000)', 'https://pubmed.ncbi.nlm.nih.gov/11180021/', '11180021', '10.1067/mcp.2000.111480', 'when mycophenolate mofetil and iron ion preparations were administered concomitantly, a remarkable decrease of mycophenolate mofetil absorption was observed.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (298, 118, '논문', 'Ferrous sulfate does not affect mycophenolic acid pharmacokinetics in kidney transplant patients (Am J Kidney Dis 2004)', 'https://pubmed.ncbi.nlm.nih.gov/15168391/', '15168391', '10.1053/j.ajkd.2004.03.021', 'Oral therapy of iron deficiency using ferrous sulfate in long-term kidney graft recipients does not impede intestinal absorption of MMF', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (299, 119, '식약처_의약품허가', '자이로릭정(알로푸리놀) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197000050', NULL, NULL, '3) 동물실험에서 철분제제와 병용하는 경우 이 약의 다량투여에 의하여 간에 철분 축적이 증가했다는 보고가 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (300, 120, '식약처_의약품허가', '콤탄정200밀리그램(엔타카폰) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199906916', NULL, NULL, '4) 이 약은 위장관에서 철과 킬레이트를 형성할 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (301, 121, '식약처_의약품허가', '코자정(로사르탄칼륨) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200811814', NULL, NULL, '2) 안지오텐신Ⅱ를 저해하는 다른 약물과 마찬가지로 칼륨보존이뇨제(예, 스피로노락톤, 트리암테렌, 아미로리드), 칼륨 보충제, 칼륨을 함유한 염분 대용제, 또는 혈청 칼륨 농도를 증가시킬 수 있는 다른 약물(예, 헤파린, 트리메토프림 함유제제)과의 병용은 혈청 칼륨 농도를 증가시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (302, 121, '식약처_의약품허가', '레니프릴정10밀리그램(에날라프릴말레산염) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200100264', NULL, NULL, '1) 혈청칼륨을 상승시키는 약물(스피로노락톤, 트리암테렌, 아밀로라이드 등 칼륨보존성 이뇨제, 칼륨보급제, 칼륨함유 염대용품)와 병용투여하는 경우에는 혈청칼륨이 증가될 수 있으므로 주의한다(특히 신기능장애 환자).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (303, 121, '식약처_의약품허가', '케이콘틴서방정(염화칼륨) 사용상의 주의사항 - 4. 복용 전 상의할 것', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200001783', NULL, NULL, '5) ACE 저해제(염산베나제프릴, 캅토프릴 등), 안지오텐신 Ⅱ 수용체 길항제(발사르탄, 로사르탄칼륨, 칸데사르탄실렉세틸, 텔미사르탄 등), 비스테로이드소염제(인도메타신 등), 사이클로스포린, 베타차단제, 헤파린, 디곡신을 투여받고 있는 환자(혈중 칼륨을 상승시키거나 병용에 의해 고칼륨혈증이 나타나기 쉽다. 신장애가 있는 환자는 특히 주의한다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (304, 121, '식약처_의약품허가', '코자정(로사르탄칼륨) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200811814', NULL, NULL, '2) 칼륨보충제 : 이 약을 복용하는 환자는 의사와 상의하지 않고 칼륨보충제 또는 칼륨을 함유하는 염분 대용제를 복용하지 않도록 한다(6. 상호작용 항 참조).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (305, 121, '식약처_의약품허가', '엔트레스토필름코팅정100밀리그램(사쿠비트릴·발사르탄나트륨염수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201602112', NULL, NULL, '5) 칼륨 농도를 증가시키는 약물 : 칼륨 보존 이뇨제(트리암테렌 등), 미네랄코르티코이드 길항제(스피로노락톤 등), 칼륨 보충제, 칼륨을 함유한 나트륨 대용제 또는 헤파린 등과 이 약을 병용투여하는 경우 혈청 칼륨 및 크레아티닌의 농도를 증가시킬 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (306, 122, '식약처_의약품허가', '알닥톤필름코팅정25밀리그람(스피로노락톤) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200409929', NULL, NULL, '2) 이 약은 칼륨이 풍부한 칼륨보급성약물 및 식품, 칼륨보존성이뇨제와 병용하는 경우에는 치명적인 고칼륨혈증을 초래할 수 있으므로 병용투여하지 않는다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (307, 122, '식약처_의약품허가', '에프레논정25밀리그램(에플레레논) 사용상의 주의사항(''다음 환자에는 투여하지 말 것 - 고혈압 치료를 받는 환자'' 항목) - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202007208', NULL, NULL, '- 칼륨 보충제 또는 칼륨 보전 이뇨제(예: 아밀로라이드, 스피로노락톤 또는 트리암테렌) 등 칼륨 제제를 투여 중인 환자', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (308, 122, '식약처_의약품허가', '케렌디아정10밀리그램(피네레논) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202201903', NULL, NULL, '혈청 칼륨을 증가시키는 약물을 이 약과 병용할 경우, 고칼륨혈증의 위험을 증가시킬 것으로 예상된다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (309, 122, '식약처_의약품허가', '케이콘틴서방정(염화칼륨) 사용상의 주의사항 - 2. 이 약을 복용하는 동안 다음의 약을 복용하지 말 것.', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200001783', NULL, NULL, '항알도스테론제(스피로노락톤 등)나 칼륨보존성 이뇨제(트리암테렌 등)(고칼륨혈증을 일으킬 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (310, 122, '논문', 'Rates of hyperkalemia after publication of the Randomized Aldactone Evaluation Study (Juurlink, N Engl J Med 2004)', 'https://pubmed.ncbi.nlm.nih.gov/15295047/', '15295047', '10.1056/NEJMoa040135', 'The rate of hospitalization for hyperkalemia rose from 2.4 per 1000 patients in 1994 to 11.0 per 1000 patients in 2001 (P<0.001)', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (311, 123, '식약처_의약품허가', '네프릴정(말레인산에날라프릴) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200401614', NULL, NULL, '1) 혈청칼륨을 상승시키는 약물(스피로노락톤, 트리암테렌, 아밀로라이드 등 칼륨보존성 이뇨제, 칼륨보급제, 칼륨함유 염대용품)와 병용투여하는 경우에는 혈청칼륨이 증가될 수 있으므로 주의한다(특히 신기능장애 환자).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (312, 123, '식약처_의약품허가', '케이콘틴서방정(염화칼륨) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200001783', NULL, NULL, '5) ACE 저해제(염산베나제프릴, 캅토프릴 등), 안지오텐신 Ⅱ 수용체 길항제(발사르탄, 로사르탄칼륨, 칸데사르탄실렉세틸, 텔미사르탄 등), 비스테로이드소염제(인도메타신 등), 사이클로스포린, 베타차단제, 헤파린, 디곡신을 투여받고 있는 환자(혈중 칼륨을 상승시키거나 병용에 의해 고칼륨혈증이 나타나기 쉽다. 신장애가 있는 환자는 특히 주의한다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (313, 123, '논문', 'Hyperkalemia in outpatients using angiotensin-converting enzyme inhibitors. How much should we worry? (Reardon, Arch Intern Med 1998)', 'https://pubmed.ncbi.nlm.nih.gov/9437375/', '9437375', '10.1001/archinte.158.1.26', 'Of 1818 patients using ACE inhibitors, 194 (11%) developed hyperkalemia.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (314, 124, '식약처_의약품허가', '프로그랍캡슐1밀리그램(타크로리무스수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200511277', NULL, NULL, '(2) 고칼륨혈증이 나타날 수 있으므로 칼륨보존성 이뇨제(아미로라이드, 스피로노락톤, 트리암테렌)의 병용 또는 칼륨의 과잉섭취는 하지 않는다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (315, 124, '식약처_의약품허가', '산디문뉴오랄연질캡슐100밀리그램(사이클로스포린) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199504165', NULL, NULL, '11) 이 약을 투여 받는 환자는 고식이성 칼륨 섭취를 피하고 칼륨 함유 약물이나 칼륨 저류성 이뇨제를 병용 투여하지 않는다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (316, 125, '식약처_의약품허가', '셉트린정 사용상의 주의사항(25항 목록에 ''칼륨제제'' 포함) - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197000049', NULL, NULL, '25) 다음 약물과의 병용투여에 의해 고칼륨혈증이 나타날 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (317, 125, '논문', 'Trimethoprim-sulfamethoxazole-induced hyperkalemia in patients receiving inhibitors of the renin-angiotensin system: a population-based study (Antoniou, Arch Intern Med 2010)', 'https://pubmed.ncbi.nlm.nih.gov/20585070/', '20585070', '10.1001/archinternmed.2010.142', 'Compared with amoxicillin, the use of trimethoprim-sulfamethoxazole was associated with a nearly 7-fold increased risk of hyperkalemia-associated hospitalization', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (318, 126, '식약처_의약품허가', '녹십자헤파린나트륨주사액 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200302231', NULL, NULL, '9) 헤파린은 알도스테론의 부신 분비를 억제하여 고칼륨혈증으로 이어질 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (319, 126, '논문', 'Heparin-induced aldosterone suppression and hyperkalemia (Oster, Am J Med 1995)', 'https://pubmed.ncbi.nlm.nih.gov/7778574/', '7778574', '10.1016/s0002-9343(99)80017-5', 'Greater than normal serum potassium levels occur in about 7% of patients, but marked hyperkalemia generally requires the presence of additional factors perturbing potassium balance', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (320, 127, '식약처_의약품허가', '야즈정 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200807400', NULL, NULL, '2) 이 약에 함유되어 있는 드로스피레논 3mg은 고위험환자에서 고칼륨혈증 가능성을 지닌 항미네랄코티코이드 활성을 가지고 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (321, 127, '논문', 'Risk of hyperkalemia in women taking ethinylestradiol/drospirenone and other oral contraceptives (Contraception 2008)', 'https://pubmed.ncbi.nlm.nih.gov/18929734/', '18929734', '10.1016/j.contraception.2008.06.012', 'EE/DRSP initiators are no more likely than other OC initiators to experience hyperkalemia or related clinical outcomes', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (322, 128, '식약처_의약품허가', '다이크로짇정(히드로클로로티아지드) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=196000008', NULL, NULL, '11) 염화칼륨을 병용투여하는 경우에는 이 약에 의해 소장궤양 또는 협착이 나타날 수 있으므로 주의한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (323, 128, '논문', 'Small bowel ulceration. An evaluation of thiazide therapy (Geriatrics 1968)', 'https://pubmed.ncbi.nlm.nih.gov/5634862/', '5634862', NULL, NULL, 'pmid_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (324, 129, '식약처_의약품허가', '티비케이정50밀리그램(돌루테그라비르나트륨) 사용상의 주의사항 - 5. 상호작용(표)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201404050', NULL, NULL, '칼슘 보충제, 철분 보충제는 돌루테그라비르의 복용과 충분한 시간 간격을 두고 복용해야 한다(칼슘 또는 철분 보충제 복용 2시간 전이나 6시간 후).', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (325, 129, '식약처_의약품허가', '빅타비정 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201900267', NULL, NULL, '이 약은 칼슘 함유 경구용 약물 또는 보충제 투여 최소 2시간 이전 또는 6시간 이후에 투여해야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (326, 129, '논문', 'Pharmacokinetics of dolutegravir when administered with mineral supplements in healthy adult subjects (J Clin Pharmacol 2015)', 'https://pubmed.ncbi.nlm.nih.gov/25449994/', '25449994', NULL, 'Plasma dolutegravir AUC(0-∞), Cmax , and C24 were reduced by 39%, 37%, and 39%, respectively, when co-administered with calcium carbonate while fasting', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (327, 130, '식약처_의약품허가', '뉴알파정1마이크로그램(알파칼시돌) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202600653', NULL, NULL, '칼슘 함유제제 또는 치아지드계 이뇨제(고칼슘혈증의 위험이 증가한다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (328, 131, '식약처_의약품허가', '레볼레이드정25밀리그램(엘트롬보팍올라민) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201002060', NULL, NULL, '킬레이트화에 의한 이 약 흡수의 유의한 감소를 피하기 위하여 제산제나 유제품, 미네랄 보충제와 같은 다가 양이온 함유 제품이나 약물을 복용하기 최소 2시간 전 또는 복용하고 최소 4시간 후에 이 약을 투여한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (329, 131, '식약처_의약품허가', '레볼레이드정25밀리그램(엘트롬보팍올라민) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201002060', NULL, NULL, '9) 약물-음식 상호작용: 이 약 50mg 단회투여와 유제품을 포함한 고열량, 고지방 식이를 병용한 결과, 혈중 엘트롬보팍 AUCinf가 59%, Cmax는 65% 감소하였다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (330, 131, '논문', 'Effects of food and antacids on the pharmacokinetics of eltrombopag in healthy adult subjects (Clin Ther 2009)', 'https://pubmed.ncbi.nlm.nih.gov/19446149/', '19446149', NULL, 'Concomitant administration of eltrombopag with high-calcium food or an antacid containing aluminum and magnesium was associated with significantly reduced systemic exposure', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (331, 132, '식약처_의약품허가', '원알파정(알파칼시돌) 사용상의 주의사항 - 2. 이 약을 복용하는 동안 다음의 약을 복용하지 말 것.', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199001232', NULL, NULL, '3) 칼슘 함유제제 또는 치아지드계 이뇨제(고칼슘혈증의 위험이 증가한다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (332, 132, '식약처_의약품허가', '로칼트롤연질캡슐0.25마이크로그람(칼시트리올) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200610653', NULL, NULL, '2) 식이 지침, 특히 칼슘제제에 관한 지침을 준수하도록 하며, 칼슘 함유제제를 무절제하게 복용하지 않도록 해야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (333, 132, '논문', 'Calcium Alkali Thiazide Syndrome: What We Need to Know (Cureus 2020)', 'https://pubmed.ncbi.nlm.nih.gov/33178509/', '33178509', '10.7759/cureus.10856', 'A subset of patients at risk for CAS also use thiazide diuretics for hypertension, making them more vulnerable to hypercalcemia and acute kidney injury.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (334, 133, '식약처_의약품허가', '독시마이신엔정100mg(독시사이클린수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201802879', NULL, NULL, '3) 칼슘, 마그네슘, 알루미늄을 함유하는 제산제 또는 이들 양이온을 함유하는 다른 약물들, 철·아연을 함유하고 있는 제제와 약용탄, 카올린, 펙틴 또는 비스무트(bismuth)염 제제에 의해 테트라사이클린계 약물의 흡수가 저하되어 효과가 저하될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (335, 133, '식약처_의약품허가', '디카맥스1000정 사용상의 주의사항(''이 약을 복용하는 동안 다음의 약을 복용하지 말 것'' 항목) - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200501369', NULL, NULL, '인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (336, 133, '식약처_의약품허가', '국제독시사이클린하이클레이트수화물캡슐100밀리그램 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198000105', NULL, NULL, '3) 칼슘, 마그네슘, 알루미늄을 함유하는 제산제 또는 이들 양이온을 함유하는 다른 약물들, 철ㆍ아연을 함유하고 있는 제제와 약용탄, 카올린, 펙틴 또는 비스무트(bismuth)염 제제에 의해 테트라사이클린계 약물의 흡수가 저하되어 효과가 저하될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (337, 133, '논문', 'Interactions with the absorption of tetracyclines (Neuvonen, Drugs 1976)', 'https://pubmed.ncbi.nlm.nih.gov/946598/', '946598', '10.2165/00003495-197611010-00004', 'Tetracyclines have a high affinity to form chelates with polyvalent metallic cations such as Fe+++, Fe++, Al+++, Mg++ and Ca++.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (338, 134, '식약처_의약품허가', '디고신정(디곡신) 사용상의 주의사항(병용 시 디기탈리스 중독 위험 약물 목록에 ''칼슘제'' 포함) - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=196300001', NULL, NULL, '1) 다음 약물과 병용투여시 디기탈리스 중독을 일으키기 쉬우므로 병용투여할 경우에는 관찰을 충분히 하고 신중히 투여한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (339, 134, '식약처_의약품허가', '디카맥스1000정 사용상의 주의사항(''복용하기 전에 의사, 치과의사, 약사와 상의할 것'' 항목) - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200501369', NULL, NULL, '(8) 강심배당체를 투여 중인 환자', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (340, 134, '식약처_의약품허가', '디고신정(디곡신) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=196300001', NULL, NULL, '1) 다음 약물과 병용투여시 디기탈리스 중독을 일으키기 쉬우므로 병용투여할 경우에는 관찰을 충분히 하고 신중히 투여한다. : 칼륨배설성 이뇨제(치아짓계 이뇨제, 에타크린산, 클로르탈리돈, 푸로세미드 등), 아미오다론, 스피로노락톤, 칼슘제, 레세르핀계 약물, 아트로핀계 약물, β-차단제, 교감신경효능약, 갑상선제제, 퀴니딘, 칼슘길항제, 이트라코나졸, 인도메타신, 프로파페논, 캅토프릴, 플레카이니드, 프라조신, 프로판텔린, 테트라사이클린, 에리스로마이신, 리튬염, 코르티코스테로이드, 카르베녹솔론, 미라베그론', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (341, 134, '식약처_의약품허가', '로칼트롤연질캡슐0.25마이크로그람(칼시트리올) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200610653', NULL, NULL, '4) 고칼슘혈증으로 인한 심부정맥이 야기될 수 있으므로 디기탈리스를 투여받고 있는 환자는 주의하여 용량을 결정해야 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (342, 134, '논문', 'Digoxin, hypercalcaemia, and cardiac conduction (Vella, Postgrad Med J 1999)', 'https://pubmed.ncbi.nlm.nih.gov/10616693/', '10616693', '10.1136/pgmj.75.887.554', 'concomitant therapy with digoxin or underlying cardiac disease can potentiate the arrhythmogenic effects of hypercalcaemia, leading to a symptomatic rhythm disorder.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (343, 135, '식약처_의약품허가', '씬지로이드정0.05밀리그램(레보티록신나트륨수화물) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200401821', NULL, NULL, '12) 칼슘제제, 세벨라머, 란타늄 등의 인산염과 결합하는 약물을 병용투여시 이 약의 흡수가 지연 또는 감소될 수 있으므로 투여간격에 주의하여 신중히 투여한다.(최소 4시간 간격)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (344, 135, '식약처_의약품허가', '씬지로이드정0.1밀리그램(레보티록신나트륨수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197400278', NULL, NULL, '12) 칼슘제제, 세벨라머, 란타늄 등의 인산염과 결합하는 약물을 병용투여시 이 약의 흡수가 지연 또는 감소될 수 있으므로 투여간격에 주의하여 신중히 투여한다.(최소 4시간 간격)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (345, 135, '식약처_기타', '의약품 복용 시 주의해야 할 식품 (식품의약품안전처 작성, 정책브리핑 게재 2022.05.17)', 'https://www.korea.kr/news/healthView.do?newsId=148901697', NULL, NULL, '칼슘이나 철 보충제, 콩 식품은 약의 흡수를 방해하므로 약 복용 후, 4시간 후에 섭취한다.', 'skipped');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (346, 135, '논문', 'Effect of calcium carbonate on the absorption of levothyroxine (JAMA 2000)', 'https://pubmed.ncbi.nlm.nih.gov/10838651/', '10838651', NULL, 'This study of 20 patients receiving long-term levothyroxine replacement therapy indicates that calcium carbonate reduces T(4) absorption and increases serum thyrotropin levels.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (347, 135, '논문', 'Absorption of levothyroxine when coadministered with various calcium formulations (Zamfirescu, Thyroid 2011)', 'https://pubmed.ncbi.nlm.nih.gov/21595516/', '21595516', '10.1089/thy.2010.0296', 'Coadministration of each of the three calcium preparations significantly reduced levothyroxine absorption by about 20%-25% compared with levothyroxine given alone.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (348, 136, '식약처_의약품허가', '마그오캡슐250mg(산화마그네슘) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199901457', NULL, NULL, '3) 다량의 우유, 칼슘제제와 병용(함께 복용(사용))시 우유 알칼리 증후군(고칼슘혈증, 고질소혈증, 알카리증 등)이 나타날 수 있으므로 충분히 관찰하고 이러한 증상이 나타나는 경우에는 투여를 중지한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (349, 136, '논문', 'Milk-alkali syndrome (Mayo Clin Proc 2009)', 'https://pubmed.ncbi.nlm.nih.gov/19252114/', '19252114', NULL, 'Physicians and the public need to be aware of the potential adverse effects of ingesting excessive amounts of calcium carbonate.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (350, 137, '식약처_의약품허가', '씨프로바이정250밀리그램(시프로플록사신염산염수화물) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201905731', NULL, NULL, '4) 유제품 또는 무기질 강화음료(예, 우유, 요구르트, 칼슘강화 오렌지주스)와 이 약을 병용투여하는 경우 이 약의 흡수가 감소하기 때문에 병용하지 않는 것이 바람직하다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (351, 137, '식약처_의약품허가', '제일크라비트정(레보플록사신) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199400461', NULL, NULL, '2) 알루미늄 또는 마그네슘 함유 제산제, 수크랄페이트, 철분 함유 제제, 칼슘 함유 제제, 아연 또는 철분이 함유된 종합비타민제제와의 병용에 의해 흡수가 저하되어 효과가 저하되는 경우가 있으므로 이 약 투여 전후 2시간 이내에는 병용하지 않는 것이 바람직하다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (352, 137, '식약처_의약품허가', '아벨록스정400밀리그람(목시플록사신염산염) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199906848', NULL, NULL, '9) 칼슘 보충제 : 고용량의 칼슘 보충제와 함께 투여할 때, 흡수율이 약간 감소한 반면에 흡수 정도는 영향을 받지 않았다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (353, 137, '논문', 'Lack of bioequivalence of ciprofloxacin when administered with calcium-fortified orange juice (J Clin Pharmacol 2002)', 'https://pubmed.ncbi.nlm.nih.gov/11936572/', '11936572', NULL, 'Twenty-four-hour ciprofloxacin AUCs were also decreased for both forms of the orange juice (22% [p < 0.001] and 38% [p < 0.001], respectively).', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (354, 137, '논문', 'Effects of aluminum hydroxide and calcium carbonate antacids on the bioavailability of ciprofloxacin (Frost, AAC 1992)', 'https://pubmed.ncbi.nlm.nih.gov/1503446/', '1503446', '10.1128/AAC.36.4.830', 'The relative bioavailability of Cipro when given with calcium carbonate was approximately 60% of the control value.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (355, 137, '논문', 'Together or Apart? Impact of Dietary Interventions on Bioavailability of Quinolones: Systematic Review with Meta-analyses (Clin Pharmacokinet 2024)', 'https://pubmed.ncbi.nlm.nih.gov/38807006/', '38807006', '10.1007/s40262-024-01377-0', 'All 14 analysed quinolones showed a substantial reduction in bioavailability when co-administered with antacids and mineral supplements, except for calcium preparations.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (356, 138, '식약처_의약품허가', '포사맥스70밀리그램정(알렌드론산나트륨수화물) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200009061', NULL, NULL, '칼슘보충제나 제산제 및 일부 경구용 약물들은 이 약의 흡수를 방해하는 것으로 알려져 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (357, 138, '식약처_의약품허가', '악토넬정35밀리그람(리세드론산나트륨) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200200772', NULL, NULL, '3) 칼슘보충제, 제산제 및 다가 양이온(칼슘, 마그네슘, 철, 알루미늄 등)을 함유한 경구투여 약물의 병용 투여는 이 약의 흡수를 방해한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (358, 138, '식약처_의약품허가', '본비바정150밀리그램(이반드론산나트륨일수화물) 사용상의 주의사항 - 5. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200607634', NULL, NULL, '2) 칼슘보조제, 제산제, 다가 양이온(알루미늄, 마그네슘, 철)을 포함한 경구투여 약물은 이 약의 흡수를 저해할 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (359, 138, '식약처_의약품허가', '악토넬EC정35밀리그램(리세드론산나트륨2.5수화물) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201205259', NULL, NULL, '2) 이 약 복용 후 칼슘 600 mg/비타민D 400 IU 보충제의 복용은 리세드론산의 흡수율을 약 38 % 감소시켰다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (360, 138, '논문', 'Studies of the oral bioavailability of alendronate (Clin Pharmacol Ther 1995)', 'https://pubmed.ncbi.nlm.nih.gov/7554702/', '7554702', NULL, 'Taking alendronate either concurrently with or 2 hours after breakfast drastically (> 85%) impaired availability.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (361, 139, '식약처_의약품허가', '환인히단토인정(페니토인) 사용상의 주의사항 - 6. 상호작용', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=197500285', NULL, NULL, '2) 다음 약물에 의해 페니토인의 농도가 감소할 수 있으므로 주의한다 : 만성 알코올 남용자, 레세르핀, 카르바마제핀, 수크랄페이트, 칼슘함유 제산제', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (362, 139, '논문', 'Effect of antacids on phenytoin bioavailability (Ther Drug Monit 1981)', 'https://pubmed.ncbi.nlm.nih.gov/7336470/', '7336470', NULL, 'Patients should be cautioned against concomitant use of antacids and phenytoin.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (363, 140, '식약처_의약품허가', '코자플러스정(로사르탄칼륨/히드로클로로티아지드) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200811608', NULL, NULL, '(15) 칼슘염류: 티아지드계 이뇨제의 병용투여는 배설 감소로 인해 혈청 칼슘 레벨이 증가될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (364, 140, '식약처_의약품허가', '미카클로정40/12.5밀리그램(텔미사르탄, 클로르탈리돈) 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202600660', NULL, NULL, '9) 칼슘염 및 비타민D : 티아지드계 이뇨제와 병용시 임상수치가 유의성 있게 증가한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (365, 140, '논문', 'Hypercalcemic crisis induced by calcium carbonate (Clin Kidney J 2012)', 'https://pubmed.ncbi.nlm.nih.gov/25874082/', '25874082', '10.1093/ckj/sfs060', 'drug-induced hypercalcemic crisis in an elderly male resulting from calcium-containing supplements facilitated by thiazide diuretic and angiotensin-converting enzyme inhibitor.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (366, 140, '논문', 'Calcium Alkali Thiazide Syndrome: What We Need to Know (Cureus 2020)', 'https://pubmed.ncbi.nlm.nih.gov/33178509/', '33178509', '10.7759/cureus.10856', 'A subset of patients at risk for CAS also use thiazide diuretics for hypertension, making them more vulnerable to hypercalcemia and acute kidney injury.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (367, 141, '식약처_의약품허가', '일성이솦틴정80밀리그램(베라파밀염산염) 사용상의 주의사항(과량투여 처치) - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199400992', NULL, NULL, '2) 처치 : 비경구적인 칼슘의 유입, β-교감신경 흥분 및 위장세척에 의해 과량투여를 치료한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (368, 141, '논문', 'Calcium and calciferol antagonise effect of verapamil in atrial fibrillation (Bar-Or, BMJ 1981, 서신)', 'https://pubmed.ncbi.nlm.nih.gov/6786574/', '6786574', '10.1136/bmj.282.6276.1585-a', NULL, 'pmid_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (369, 142, '식약처_의약품허가', '경보세프트리악손나트륨수화물주1그램 사용상의 주의사항 - 의약품안전나라', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=199800361', NULL, NULL, '1) 이 약은 칼슘함유용액 또는 약물과 혼합해서는 안되며, 각각 분리된 주입구일지라도 동시에 투여해서는 안된다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (370, 143, '논문', 'Interaction of atenolol with furosemide and calcium and aluminum salts (Kirch, Clin Pharmacol Ther 1981)', 'https://pubmed.ncbi.nlm.nih.gov/7285476/', '7285476', '10.1038/clpt.1981.184', 'Calcium altered atenolol kinetics distinctly mean peak plasma levels of atenolol fell 51% (P less than 0.001)', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (371, 144, '논문', 'New medications which decrease levothyroxine absorption (John-Kalarickal, Thyroid 2007)', 'https://pubmed.ncbi.nlm.nih.gov/17725434/', '17725434', '10.1089/thy.2007.0060', 'Sevelamer hydrochloride and chromium picolinate each significantly (p < 0.05) decreased the area under the serum thyroxine concentration curve, while ezetimibe had no effect.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (372, 145, '식약처_건강기능식품', '「건강기능식품의 기준 및 규격」 일부개정고시(제2020-92호) 제3.1.1-25 크롬 (3) 섭취 시 주의사항', 'https://www.mfds.go.kr/brd/m_207/down.do?brd_id=data0008&seq=14585&data_tp=A&file_seq=1', NULL, NULL, '(가) 당뇨병이 있는 경우 섭취 전 전문가와 상담할 것', 'skipped');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (373, 146, '논문', 'Systematic review and meta-analysis of the efficacy and safety of chromium supplementation in diabetes (Suksomboon, J Clin Pharm Ther 2014)', 'https://pubmed.ncbi.nlm.nih.gov/24635480/', '24635480', '10.1111/jcpt.12147', 'Overall, chromium mono- and combined supplementation significantly improved glycaemic control', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (374, 147, '논문', 'A comparison of the efficacy and toxic effects of sustained- vs immediate-release niacin in hypercholesterolemic patients (JAMA 1994)', 'https://pubmed.ncbi.nlm.nih.gov/8309029/', '8309029', NULL, 'None of the patients taking IR niacin developed hepatotoxic effects, while 12 (52%) of the 23 patients taking SR niacin did.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (375, 148, '식약처_건강기능식품', '「건강기능식품의 기준 및 규격」 일부개정고시(제2020-92호, 2020.9.23.) 식약처 공지', 'https://www.mfds.go.kr/brd/m_207/view.do?seq=14585', NULL, NULL, '2019년 건강기능식품 재평가 결과에 따라 베타카로틴, 비타민 K, 비타민 B1, 비타민 B2, 판토텐산, 비타민 B12, 비오틴, 칼륨, 크롬의 섭취 시 주의사항과 크롬의 기능성 내용을 신설하고', 'skipped');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (376, 148, '논문', 'Effects of a combination of beta carotene and vitamin A on lung cancer and cardiovascular disease (N Engl J Med 1996, CARET)', 'https://pubmed.ncbi.nlm.nih.gov/8602180/', '8602180', NULL, 'The active-treatment group had a relative risk of lung cancer of 1.28 (95 percent confidence interval, 1.04 to 1.57; P=0.02)', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (377, 149, '논문', 'Reduction in plasma or skin alpha-tocopherol concentration with long-term oral administration of beta-carotene in humans and mice (J Natl Cancer Inst 1992)', 'https://pubmed.ncbi.nlm.nih.gov/1404449/', '1404449', NULL, 'The greatest decrease was observed during the 9th (last) month of dosing, with a decrease of 40% from baseline.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (378, 150, '식약처_의약품허가', '멀티비타원프리미엄정 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200800955', NULL, NULL, '이 제품에 함유된 비타민A는 정상적인 식이에서 충분히 공급되므로 보조요법의 용량은 1일 5,000IU이상을 넘지 않도록 한다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (379, 150, '식약처_의약품허가', '아이간유연질캡슐 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202400727', NULL, NULL, '임부에 비타민 A(레티놀)를 1일 5,000 IU 이상 투여하는 경우에는 선천성 기형을 유발할 위험이 있으므로 임신 3개월 이내 또는 임신하고 있을 가능성이 있는 여성에는 비타민 A를 5,000 IU/일 이상 투여하지 말 것', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (380, 150, '논문', 'Teratogenicity of high vitamin A intake (N Engl J Med 1995)', 'https://pubmed.ncbi.nlm.nih.gov/7477116/', '7477116', NULL, 'Using a smoothed regression curve, we found an apparent threshold near 10,000 IU per day of supplemental vitamin A.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (381, 150, '논문', 'Liver damage caused by therapeutic vitamin A administration: estimate of dose-related toxicity in 41 cases (Gastroenterology 1991)', 'https://pubmed.ncbi.nlm.nih.gov/2019375/', '2019375', NULL, 'The smallest continuous daily consumption leading to cirrhosis was 25,000 IU during 6 years', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (382, 150, '논문', '2020 한국인 영양소 섭취기준: 비타민 A (J Nutr Health 2022)', 'https://koreascience.kr/article/JAKO202213650055298.pdf', NULL, '10.4163/jnh.2022.55.2.201', '비타민 A의 과잉섭취는 다양한 독성이 나타날 수 있으므로 상한섭취량 이내로 섭취해야 한다.', 'no_pmid');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (383, 151, '식약처_의약품허가', '아이간유연질캡슐 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202400727', NULL, NULL, '장기간 고용량의 비타민 A(베타카로틴으로부터 전환된 것을 제외한) 섭취는 폐경기를 지난 여성의 골다공증(뼈엉성증) 위험을 높일 수 있다', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (384, 151, '논문', 'Vitamin A antagonizes calcium response to vitamin D in man (J Bone Miner Res 2001)', 'https://pubmed.ncbi.nlm.nih.gov/11585356/', '11585356', NULL, 'retinyl palmitate intake resulted in a significant decrease in S-calcium when taken alone (-1.0%; p < 0.05) and diminished the calcium response to 1,25(OH)2D3', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (385, 151, '논문', 'Excessive dietary intake of vitamin A is associated with reduced bone mineral density and increased risk for hip fracture (Ann Intern Med 1998)', 'https://pubmed.ncbi.nlm.nih.gov/9841582/', '9841582', NULL, 'For every 1-mg increase in daily intake of retinol, risk for hip fracture increased by 68% (95% CI, 18% to 140%; P for trend, 0.006).', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (386, 151, '논문', 'Vitamin A intake and hip fractures among postmenopausal women (JAMA 2002)', 'https://pubmed.ncbi.nlm.nih.gov/11754708/', '11754708', NULL, 'Long-term intake of a diet high in retinol may promote the development of osteoporotic hip fractures in women.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (387, 152, '식약처_의약품허가', '뉴로비정300밀리그램(피리독신염산염) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=202200702', NULL, NULL, '피리독신을 1일 50 mg 이상의 용량으로 장기간 투여시 감각 이상(paresthesias) 등 말초신경병증이 보고된 바 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (388, 152, '식약처_의약품허가', '멀티비타원프리미엄정 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200800955', NULL, NULL, '피리독신을 1일 500㎎~2g의 용량으로 장기간 복용하면 감각신경병 또는 신경병적 증상(neuropathy : 말초신경계의 기능적 장애 또는 병적변화)이 나타날 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (389, 152, '논문', 'Sensory neuropathy from pyridoxine abuse. A new megavitamin syndrome (N Engl J Med 1983)', 'https://pubmed.ncbi.nlm.nih.gov/6308447/', '6308447', NULL, 'this report indicates that it can cause sensory neuropathy or neuronopathy syndromes', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (390, 152, '논문', 'Underestimated pyridoxine consumption and neurotoxicity: a case-based review (Rheumatol Int 2025)', 'https://pubmed.ncbi.nlm.nih.gov/40418248/', '40418248', NULL, 'All of them had a history of excessive vitamin B6 consumption, though through different sources.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (391, 153, '식약처_의약품허가', '유한비타민씨정1000mg 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200100586', NULL, NULL, '신장(콩팥)의 수산결석(수산칼슘돌) 환자 : 1일 1 g 이상 투여할 경우', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (392, 153, '논문', 'Total, Dietary, and Supplemental Vitamin C Intake and Risk of Incident Kidney Stones (Am J Kidney Dis 2016)', 'https://pubmed.ncbi.nlm.nih.gov/26463139/', '26463139', NULL, 'Total and supplemental vitamin C intake was significantly associated with higher risk for incident kidney stones in men, but not in women.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (393, 153, '논문', '2020 한국인 영양소 섭취기준: 비타민 C (J Nutr Health 2022)', 'https://koreascience.kr/article/JAKO202231558096678.pdf', NULL, '10.4163/jnh.2022.55.5.523', '따라서 상한섭취량은 건강한 사람에서 위장관장애 증상이 나타나지 않을 정도의 양을 근거로 설정하였다.', 'no_pmid');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (394, 154, '논문', 'Destruction of vitamin B12 by ascorbic acid (JAMA 1974) - 초록 없음', 'https://pubmed.ncbi.nlm.nih.gov/4479087/', '4479087', NULL, NULL, 'pmid_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (395, 154, '논문', 'Stability of vitamin B12 in the presence of ascorbic acid (Am J Clin Nutr 1976)', 'https://pubmed.ncbi.nlm.nih.gov/1274888/', '1274888', NULL, 'there was no deleterious effect of added ascorbic acid on the vitamin B12 content of meals, contrary to their published results.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (396, 155, '식약처_의약품허가', '디맥정(농축콜레칼시페롤과립) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201309386', NULL, NULL, '다른 비타민 D 제제를 복용하는 경우(용량이 조절되어야 함)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (397, 155, '논문', 'A review of the growing risk of vitamin D toxicity from inappropriate practice (Br J Clin Pharmacol 2018)', 'https://pubmed.ncbi.nlm.nih.gov/29498758/', '29498758', NULL, 'Many of these cases are a consequence of inappropriate prescribing, and the use of high-dose over-the-counter preparations or unlicensed preparations.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (398, 156, '식약처_의약품허가', '그랑페롤연질캡슐400아이유 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198700431', NULL, NULL, '비타민 A, K제를 복용 중인 환자(고용량 복용시 체내에 저장된 비타민 A를 고갈시키고 비타민 K의 흡수 및 작용을 저해할 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (399, 156, '논문', 'Effect of vitamin E supplementation on vitamin K status in adults with normal coagulation status (Am J Clin Nutr 2004)', 'https://pubmed.ncbi.nlm.nih.gov/15213041/', '15213041', NULL, 'High-dose vitamin E supplementation increased PIVKA-II in adults not receiving oral anticoagulant therapy.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (400, 157, '식약처_의약품허가', '그랑페롤연질캡슐400아이유 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198700431', NULL, NULL, '비타민 A, K제를 복용 중인 환자(고용량 복용시 체내에 저장된 비타민 A를 고갈시키고 비타민 K의 흡수 및 작용을 저해할 수 있다.)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (401, 158, '식약처_의약품허가', '녹십자폴산정 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201803375', NULL, NULL, '악성빈혈 환자(투여 시, 혈액상태는 개선되나 신경증상에는 효과가 없으므로 비타민 B12 제제를 병용할 것. 단, 진단이 확립되지 않는 악성빈혈 환자의 경우 혈액상태의 개선에 의해 악성빈혈을 은폐하여 진단 및 치료에 영향을 줄 수 있으므로 주의할 것)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (402, 158, '식약처_의약품허가', '일동폴산정1밀리그램 사용상의 주의사항(의약품안전나라 허가정보)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201405494', NULL, NULL, '악성빈혈 환자(투여 시, 혈액상태는 개선되나 신경증상에는 효과가 없으므로 비타민 B12 제제를 병용할 것. 단, 진단이 확립되지 않는 악성빈혈 환자의 경우 혈액상태의 개선에 의해 악성빈혈을 은폐하여 진단 및 치료에 영향을 줄 수 있으므로 주의할 것)', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (403, 158, '논문', 'Folate and vitamin B-12 status in relation to anemia, macrocytosis, and cognitive impairment in older Americans in the age of folic acid fortification (Am J Clin Nutr 2007)', 'https://pubmed.ncbi.nlm.nih.gov/17209196/', '17209196', NULL, 'In seniors with low vitamin B-12 status, high serum folate was associated with anemia and cognitive impairment.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (404, 158, '논문', 'What is the safe upper intake level of folic acid for the nervous system? (Eur J Clin Nutr 2016)', 'https://pubmed.ncbi.nlm.nih.gov/26862004/', '26862004', NULL, 'evidence of neurological harm from long-term exposure to doses of folic acid between 0.5 and 1 mg in the presence of vitamin B12 deficiency', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (405, 159, '식약처_의약품허가', '셀레나제100마이크로그램퍼오랄액(아셀렌산나트륨오수화물) 사용상의 주의사항 - 2. 이 약을 복용하는 동안 다음의 약을 복용하지 말 것.', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200511943', NULL, NULL, '비타민C와 같은 환원제가 이 약을 침전시킬 수 있으므로 이 약과 함께 복용하지 말아야 하며, 만일 비타민C를 복용하려면 이 약과 약 4시간의 간격을 두고 따로 복용해야 함.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (406, 159, '논문', 'Ascorbic acid-selenite interactions in humans studied with an oral dose of 74SeO3(2-) (Am J Clin Nutr 1989)', 'https://pubmed.ncbi.nlm.nih.gov/2718921/', '2718921', NULL, 'Limiting dietary ascorbic acid to about 20 mg/d appeared to reduce the time-related retention of absorbed selenite and the size of Se-EMP.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (407, 160, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '아스코르빈산(비타민 C) 200 ㎎ 이상과 함께 복용하는 경우 철분의 흡수가 증가 될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (408, 160, '식약처_의약품허가', '훼럼포유연질캡슐 사용상의 주의사항 - 9. 기타 이 약의 복용시 주의할 사항', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201805238', NULL, NULL, '4) 아스코르브산(비타민 C) 200 ㎎ 이상과 함께 복용하는 경우 철분의 흡수가 증가될 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (409, 160, '논문', 'Congestive cardiomyopathy and haemochromatosis--rapid progression possibly accelerated by excessive ingestion of ascorbic acid (Aust N Z J Med 1982)', 'https://pubmed.ncbi.nlm.nih.gov/6953962/', '6953962', NULL, 'He had for twelve months ingested large amounts of ascorbic acid and was admitted with severe heart failure having been symptomatic for two months.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (410, 160, '논문', 'Effect of ascorbic acid intake on nonheme-iron absorption from a complete diet (Am J Clin Nutr 2001)', 'https://pubmed.ncbi.nlm.nih.gov/11124756/', '11124756', NULL, 'The facilitating effect of vitamin C on iron absorption from a complete diet is far less pronounced than that from single meals.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (411, 161, '논문', 'Influence of ascorbic acid supplementation on copper status in young adult men (Am J Clin Nutr 1983)', 'https://pubmed.ncbi.nlm.nih.gov/6837490/', '6837490', NULL, 'this study confirms that a high ascorbic acid intake is antagonistic to copper status of men', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (412, 162, '식약처_의약품허가', '디카맥스디플러스정 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200802864', NULL, NULL, '장기 투여에 의해 고칼슘혈증 및 결석증이 나타날 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (413, 162, '논문', 'Urinary tract stone occurrence in the Women''s Health Initiative (WHI) randomized clinical trial of calcium and vitamin D supplements (Am J Clin Nutr 2011)', 'https://pubmed.ncbi.nlm.nih.gov/21525191/', '21525191', NULL, 'Daily supplementation with CaD for 7 y was associated with an increase in the number of self-reported urinary tract stones.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (414, 162, '논문', 'Calcium supplements with or without vitamin D and risk of cardiovascular events: reanalysis of the WHI limited access dataset and meta-analysis (BMJ 2011)', 'https://pubmed.ncbi.nlm.nih.gov/21505219/', '21505219', NULL, 'Calcium supplements with or without vitamin D modestly increase the risk of cardiovascular events, especially myocardial infarction', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (415, 162, '논문', 'Got calcium? Welcome to the calcium-alkali syndrome (J Am Soc Nephrol 2010)', 'https://pubmed.ncbi.nlm.nih.gov/20413609/', '20413609', NULL, 'The incidence of the calcium-alkali syndrome is growing in large part as a result of the widespread use of over-the-counter calcium and vitamin D supplements', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (416, 163, '식약처_의약품허가', '그랑페롤연질캡슐400아이유 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=198700431', NULL, NULL, '이 약을 1일 체중 kg당 10 IU 이상 복용할 경우, 철결핍성빈혈 어린이의 철분제 투여에 대한 반응을 지연시킬 수 있으며 철분공급을 실시하는 저체중 영아(갓난아기)에게 비타민 E 결핍성 용혈성(적혈구 파괴성)빈혈을 초래할 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (417, 163, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '퀴놀론계, 페니실라민, 콜레스티라민, 췌장엑스 및 비타민 E와 같은 제제를 복용중인 사람', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (418, 163, '논문', 'Role of dietary iron and fat on vitamin E deficiency anemia of infancy (N Engl J Med 1975)', 'https://pubmed.ncbi.nlm.nih.gov/1117912/', '1117912', NULL, 'It appears that the development of vitamin E deficiency anemia occurs in infants receiving iron supplementation.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (419, 164, '논문', 'Effect of oral folic acid supplements on zinc, copper, and iron absorption and excretion (Am J Clin Nutr 1984)', 'https://pubmed.ncbi.nlm.nih.gov/6711464/', '6711464', NULL, 'During all dietary periods urinary zinc excretion was reduced by about 50% by folic acid supplementation.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (420, 165, '논문', 'Competitive inhibition of iron absorption by manganese and zinc in humans (Am J Clin Nutr 1991)', 'https://pubmed.ncbi.nlm.nih.gov/2058577/', '2058577', NULL, 'Manganese inhibited iron absorption both in solutions and in a hamburger meal.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (421, 165, '논문', 'Manganese absorption and retention by young women is associated with serum ferritin concentration (Am J Clin Nutr 1999)', 'https://pubmed.ncbi.nlm.nih.gov/10393136/', '10393136', NULL, 'Absorption was greatest in subjects with low ferritin concentrations when they were consuming the low-manganese diet', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (422, 166, '식약처_의약품허가', '셀레나제100마이크로그램퍼오랄액 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200511943', NULL, NULL, '과량복용 시 급성증상으로 입에서 마늘 냄새가 나고, 피로, 메스꺼움, 설사 및 복통 등이 나타날 수 있다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (423, 166, '논문', '셀레늄의 2020 한국인 영양소 섭취기준 개정 및 권장식단의 셀레늄 함량 평가 (J Nutr Health 2022)', 'https://koreascience.kr/article/JAKO202226461023414.pdf', NULL, '10.4163/jnh.2022.55.4.430', '한국 성인의 셀레늄 상한섭취량은 400 µg/일로 결정하였다.', 'no_pmid');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (424, 166, '논문', 'Acute selenium toxicity associated with a dietary supplement (Arch Intern Med 2010)', 'https://pubmed.ncbi.nlm.nih.gov/20142570/', '20142570', NULL, 'The source of the outbreak was identified as a liquid dietary supplement that contained 200 times the labeled concentration of selenium.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (425, 166, '논문', 'Effects of long-term selenium supplementation on the incidence of type 2 diabetes: a randomized trial (Ann Intern Med 2007)', 'https://pubmed.ncbi.nlm.nih.gov/17620655/', '17620655', NULL, 'Selenium supplementation does not seem to prevent type 2 diabetes, and it may increase risk for the disease.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (426, 167, '논문', 'Effect of zinc supplementation on copper status in adult man (Am J Clin Nutr 1984)', 'https://pubmed.ncbi.nlm.nih.gov/6486080/', '6486080', NULL, 'This suggested that the zinc supplements decreased the copper status of the experimental group.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (427, 167, '논문', 'Iron, copper, and zinc status: response to supplementation with zinc or zinc and iron in adult females (Am J Clin Nutr 1989)', 'https://pubmed.ncbi.nlm.nih.gov/2912000/', '2912000', NULL, 'Supplementation with Zn poses a risk to Fe and Cu status.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (428, 167, '논문', 'Zinc-induced copper deficiency: a report of three cases initially recognized on bone marrow examination (Am J Clin Pathol 2005)', 'https://pubmed.ncbi.nlm.nih.gov/15762288/', '15762288', NULL, 'Excess zinc ingestion is among the causes of copper deficiency.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (429, 167, '논문', 'Zinc-Induced Hematologic Toxicities: A Systematic Review of Descriptive Studies (Biol Trace Elem Res 2026)', 'https://pubmed.ncbi.nlm.nih.gov/42087025/', '42087025', NULL, 'Serum copper levels were reduced in all patients.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (430, 167, '논문', 'Copper deficiency myelopathy produces a clinical picture like subacute combined degeneration (Neurology 2004)', 'https://pubmed.ncbi.nlm.nih.gov/15249607/', '15249607', NULL, 'A high or high-normal serum zinc level was seen in 7 of the 11 patients for whom this information was available.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (431, 167, '논문', '2020 한국인 영양소 섭취기준: 아연 (J Nutr Health 2022)', 'https://koreascience.kr/article/JAKO202226461024414.pdf', NULL, '10.4163/jnh.2022.55.4.441', '아연 평균필요량과 권장섭취량은 6–10 mg/day이고, 상한섭취량은 35 mg/day로 제시되고 있다.', 'no_pmid');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (432, 168, '논문', 'Inhibitory effects of zinc on magnesium balance and magnesium absorption in man (J Am Coll Nutr 1994)', 'https://pubmed.ncbi.nlm.nih.gov/7836627/', '7836627', NULL, 'Zn supplements of 142 mg/day decreased Mg absorption and the Mg balance significantly during all Ca intakes for the three groups combined.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (433, 169, '논문', 'Iodine-induced hyperthyroidism in a patient with a normal thyroid gland (Postgrad Med J 1986)', 'https://pubmed.ncbi.nlm.nih.gov/3748931/', '3748931', NULL, 'We report the case of a 72 year old female who developed clinical and laboratory evidence of hyperthyroidism while ingesting sea-kelp (Vitalia) tablets.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (434, 169, '논문', 'Iodine-induced hyperthyroidism (iodine-induced Basedow''s disease): a current disease picture (Schweiz Med Wochenschr 1999)', 'https://pubmed.ncbi.nlm.nih.gov/10407936/', '10407936', NULL, 'Clinical features were predominantly tachyarrhythmias and heart failure, while 6 of 8 patients had goitre', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (435, 169, '논문', 'Elemental Composition of Algae-Based Supplements by Energy Dispersive X-ray Fluorescence (Plants 2021)', 'https://pubmed.ncbi.nlm.nih.gov/34685850/', '34685850', NULL, 'the levels observed might well contribute to an excess in the human body, which can cause dysfunction of the thyroid gland.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (436, 170, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 허가사항 사용상의 주의사항 (의약품안전나라) - 상의 대상', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '철 함유제제(철제, MRI용 간장 조영제 등)를 투여중인 환자', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (437, 171, '논문', 'Studies on the bioavailability of zinc in humans: effects of heme and nonheme iron on the absorption of zinc (Am J Clin Nutr 1981)', 'https://pubmed.ncbi.nlm.nih.gov/7223699/', '7223699', NULL, 'a ratio of Fe/Zn of 1:1 slightly inhibited zinc absorption while Fe/Zn ratio of 2:1 and 3:1 substantially inhibited zinc uptake', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (438, 171, '논문', 'Competitive inhibition of iron absorption by manganese and zinc in humans (Am J Clin Nutr 1991)', 'https://pubmed.ncbi.nlm.nih.gov/2058577/', '2058577', NULL, 'a fivefold excess of zinc to iron (15 mgZn/3 mg Fe) reduced iron absorption by 56% when given in a water solution', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (439, 171, '논문', 'Iron and zinc interactions in humans (Am J Clin Nutr 1998)', 'https://pubmed.ncbi.nlm.nih.gov/9701159/', '9701159', NULL, 'when iron and zinc are given in a meal, this effect is not observed', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (440, 172, '식약처_의약품허가', '훼로바-유서방정(건조황산제일철) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200101738', NULL, NULL, '이 약을 복용하는 동안 다음의 약을 복용하지 말 것. 1) 인산염, 칼슘염', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (441, 172, '식약처_의약품허가', '훼럼포유연질캡슐 사용상의 주의사항 - 5. 이 약을 복용하는 동안 다음의 약을 복용하지 말 것.', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201805238', NULL, NULL, '1) 인산염, 칼슘염', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (442, 172, '논문', 'Calcium: effect of different amounts on nonheme- and heme-iron absorption in humans (Am J Clin Nutr 1991)', 'https://pubmed.ncbi.nlm.nih.gov/1984335/', '1984335', NULL, 'Iron absorption was reduced by 50-60% at doses of 300-600 mg Ca.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (443, 172, '논문', 'Calcium supplementation: effect on iron absorption (Am J Clin Nutr 1991)', 'https://pubmed.ncbi.nlm.nih.gov/1984334/', '1984334', NULL, 'All calcium supplements inhibited absorption of the iron supplement when taken with food.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (444, 173, '식약처_의약품허가', '디카맥스디플러스정 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=200802864', NULL, NULL, '이 약을 복용하는 동안 다음의 약을 복용하지 말 것. - 인산염, 칼슘염, 경구용 테트라사이클린계 제제, 제산제', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (445, 173, '논문', 'Got calcium? Welcome to the calcium-alkali syndrome (J Am Soc Nephrol 2010)', 'https://pubmed.ncbi.nlm.nih.gov/20413609/', '20413609', NULL, 'The calcium-alkali syndrome is now the third most common cause of hospital admission for hypercalcemia', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (446, 173, '논문', 'Calcium supplements with or without vitamin D and risk of cardiovascular events (BMJ 2011)', 'https://pubmed.ncbi.nlm.nih.gov/21505219/', '21505219', NULL, 'Calcium supplements with or without vitamin D modestly increase the risk of cardiovascular events, especially myocardial infarction', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (447, 174, '논문', 'Magnesium balance in adolescent females consuming a low- or high-calcium diet (Am J Clin Nutr 1996)', 'https://pubmed.ncbi.nlm.nih.gov/8644692/', '8644692', NULL, 'alterations in magnesium utilization should not be anticipated in adolescent females consuming a high-calcium diet', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (448, 175, '식약처_의약품허가', '라이트징크시럽(황산아연일수화물) 허가사항 사용상의 주의사항 (의약품안전나라)', 'https://nedrug.mfds.go.kr/pbp/CCBBB01/getItemDetail?itemSeq=201206329', NULL, NULL, '이 약을 투여할 경우에는 인산염, 칼슘염, 경구용테트라사이클린계 제제, 제산제와 병용투여하지 않는다.', 'quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (449, 175, '논문', 'High dietary calcium intakes reduce zinc absorption and balance in humans (Am J Clin Nutr 1997)', 'https://pubmed.ncbi.nlm.nih.gov/9174476/', '9174476', NULL, 'Zinc absorption was reduced significantly by 50% when the calcium supplement was given with the meal.', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (450, 176, '논문', 'Intestinal absorption, serum clearance, and interactions between lutein and beta-carotene when administered to human adults in separate or combined oral doses (Am J Clin Nutr 1995)', 'https://pubmed.ncbi.nlm.nih.gov/7661123/', '7661123', NULL, 'beta-carotene significantly reduced the serum AUC values for lutein to 54-61% of control values (P < 0.025)', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (451, 177, '논문', 'Effects of vitamin E on stroke subtypes: meta-analysis of randomised controlled trials (BMJ 2010)', 'https://pubmed.ncbi.nlm.nih.gov/21051774/', '21051774', NULL, 'vitamin E increased the risk for haemorrhagic stroke by 22% and reduced the risk of ischaemic stroke by 10%', 'pmid_ok_quote_ok');
INSERT INTO nutrient_interaction_source (id, interaction_id, kind, title, url, pmid, doi, quote, verified) VALUES (452, 177, '논문', 'No impact of fish oil supplements on bleeding risk: a systematic review (Dan Med J 2017)', 'https://pubmed.ncbi.nlm.nih.gov/28552094/', '28552094', NULL, 'Fish oil exposure in surgical patients did not increase bleeding or blood transfusions either during or after surgery.', 'pmid_ok_quote_ok');
